import { listRestrictedOpenItems } from "@/lib/chartAccess";
import { listContentGaps, CONTENT_GAP_LABEL, contentGapKey, isContentGapOwner } from "./flagJourneys";
import { countyReminders } from "@/lib/countyReporting";
import { contentReviewQueue } from "@/lib/contentPublishing";
import { contentVisibleToStaff } from "@/lib/contentStaff";
/** §A3 — clinical reviewers who get "Content review waiting". */
export const CONTENT_REVIEWER_ROLES: StaffRole[] = ["pmhnp", "physician", "clinical_coordinator"];
import { staleContentFor } from "./contentStaff";
import { contentType } from "./contentTypes";
import { AdelanteEHR, type Appointment } from "@/lib/ehr";
import { filterSudMedsForRole, roleSeesAsamSection } from "@/lib/asamReporting";
import { asamTaskRows } from "@/lib/asamReporting";
import { hieFollowUps } from "@/lib/hie";
import { isInFacilityTask, inFacilityEnabled } from "@/lib/inFacility";
import { myCaseload, myContactsDue, myPendingLabs, myPendingRefills, myPlanReviewsDue, screenerDueRows, staffAliases, type ActingIdentity } from "@/lib/myWork";
import { listUnsignedWork } from "@/lib/unsignedWork";
import { authorOutItems, AUTHOR_OUT_LABEL, isCrisisNote, noteClock, overdueCrisisNotes } from "@/lib/noteClock";
import { crisisSlaState, crisisSlaTarget, overdueByLabel } from "@/lib/crisisPolicy";
import { listMatchReviews } from "@/lib/patientMatching";
import { chaseRowsFor } from "@/lib/referralChase";
import { openSeverityFlags, severityAssignee, SEVERITY_ROW_LABEL } from "@/lib/severityFlags";
import { isPrescriberRole, STAFF_ROSTER, type StaffRole } from "@/lib/roles";
import { myOpenEscalations, hoursMinutesLeft } from "@/lib/escalations";
import { listRescheduleItems } from "@/lib/workingCalendar";
import { listThreadsFor, openMentionsFor } from "@/lib/staffThreads";
import { continuityTasks, continuityTaskLabel } from "@/lib/medContinuity";
import { releaseCoverageRows, releaseCoverageDueAt, dayOffsetLabel } from "@/lib/coverageRelease";
import { reassignNeededItems } from "@/lib/staffLifecycle";
import { NEUTRAL_TYPE_LABEL } from "@/lib/escalations";

export type WorkspaceTileId = "schedule" | "actions" | "caseload" | "requests" | "coordinator" | "scheduling";
export type ScheduleSegment = "up_next" | "in_progress" | "done" | "closed";
export type ActionGroup = "now" | "today" | "week";
export type WorkspaceActionKind = "closing" | "unsigned" | "cosign" | "refill" | "crisis" | "screener" | "asam" | "lab" | "plan" | "outside" | "switch" | "contact" | "task" | "match" | "chase" | "crisis_note" | "severity" | "escalation" | "reply" | "author_out" | "reschedule" | "continuity" | "coverage" | "reassign_needed" | "content_review" | "restricted_open" | "county_reminder" | "content_waiting" | "content_gap";
export interface WorkspaceActionRow {
  id: string;
  kind: WorkspaceActionKind;
  patientId: string;
  patientName: string;
  label: string;
  due: string;
  dueAt: string;
  group: ActionGroup;
  action: string;
  sourceId?: string;
}

const CARE_ROLES: readonly StaffRole[] = ["ecm_provider", "cf_care_manager", "peer_specialist", "community_health_worker"];
export const isCareRole = (role: StaffRole) => CARE_ROLES.includes(role);
export const isCoordinatorRole = (role: StaffRole) => role === "clinical_coordinator" || role === "sys_admin";
/** R53 part 2 (Draft — pending clinical sign-off): clinician workspaces show screener rows in the Re-screens due tile. */
export const rescreenTileRole = (role: StaffRole) => !isCoordinatorRole(role) && !isCareRole(role);
/** Today tiles as rendered (Today 4–6 tile rule): existing order plus Re-screens due after Needs my action. */
export function workspaceTodayTiles(role: StaffRole): (WorkspaceTileId | "rescreens")[] {
  const order: (WorkspaceTileId | "rescreens")[] = [...workspaceTileOrder(role)];
  if (rescreenTileRole(role)) order.splice(order.indexOf("actions") + 1, 0, "rescreens");
  return order;
}

export function workspaceTileOrder(role: StaffRole): WorkspaceTileId[] {
  // §Scheduling S4 — coordination roles schedule from the Scheduling tile
  // (caseload / all-clinician visits, requests, "Book a visit").
  if (isCoordinatorRole(role)) return ["coordinator", "scheduling", "actions"];
  if (isCareRole(role)) return ["actions", "scheduling", "caseload"];
  return ["schedule", "actions", "caseload", "requests"];
}

export function scheduleSegments(appts: Appointment[], now = new Date()) {
  const sameDay = (iso: string) => new Date(iso).toDateString() === now.toDateString();
  const today = appts.filter((a) => sameDay(a.start)).sort((a, b) => a.start.localeCompare(b.start));
  return {
    up_next: today.filter((a) => a.status === "scheduled" && +new Date(a.start) + a.durationMin * 60000 > +now),
    in_progress: today.filter((a) => a.status === "checked_in"),
    done: today.filter((a) => a.status === "attended"),
    closed: today.filter((a) => ["cancelled", "no_show", "late_cancel", "rescheduled"].includes(a.status)),
  } satisfies Record<ScheduleSegment, Appointment[]>;
}

const groupFor = (iso: string, now: Date): ActionGroup => {
  const due = +new Date(iso);
  if (due <= +now) return "now";
  const end = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 59, 59, 999).getTime();
  return due <= end ? "today" : "week";
};
const dueText = (iso: string, now: Date) => {
  const d = +new Date(iso) - +now;
  if (d <= 0) return "Due now";
  if (d < 86400000) return "Due today";
  return `Due ${new Date(iso).toLocaleDateString("en-US", { weekday: "short" })}`;
};

export function workspaceActionRows(input: {
  actor: ActingIdentity & { role: StaffRole };
  needsClosing: Appointment[];
  now?: Date;
}): WorkspaceActionRow[] {
  const { actor, needsClosing } = input;
  const now = input.now ?? new Date();
  const patients = AdelanteEHR.listPatients();
  const mine = myCaseload(actor);
  const mineIds = new Set(mine.map((p) => p.id));
  const aliases = staffAliases(actor);
  const rows: WorkspaceActionRow[] = [];
  const push = (row: Omit<WorkspaceActionRow, "group" | "due">) => rows.push({ ...row, group: groupFor(row.dueAt, now), due: dueText(row.dueAt, now) });
  for (const a of needsClosing) {
    const p = patients.find((x) => x.id === a.patientId);
    push({ id: `closing:${a.id}`, kind: "closing", patientId: a.patientId, patientName: p ? `${p.firstName} ${p.lastName}` : "Patient", label: a.status === "attended" ? "Visit needs a note" : "Past visit needs closing", dueAt: new Date(+new Date(a.start) + a.durationMin * 60000).toISOString(), action: a.status === "attended" ? "Write note" : "Mark attended" });
  }
  for (const u of listUnsignedWork({ authorId: actor.clinicianId ?? actor.staffId })) {
    if (u.kind === "undocumented_encounter" && needsClosing.some((a) => a.id === u.id)) continue;
    const name = `${u.patient.firstName} ${u.patient.lastName}`;
    if (u.kind === "draft_note" && u.note) {
      // §Batch C3 — business-day / crisis clocks (Draft — pending clinical sign-off).
      const c = noteClock(u.note, now);
      if (isCrisisNote(u.note)) { rows.push({ id: `crisis_note:${u.id}`, kind: "crisis_note", patientId: u.patient.id, patientName: name, label: "Crisis note to sign", dueAt: c.dueAt, due: c.label, group: "now", action: "Review note", sourceId: u.id }); continue; }
      rows.push({ id: `unsigned:${u.id}`, kind: "unsigned", patientId: u.patient.id, patientName: name, label: "Unsigned note", dueAt: c.dueAt, due: c.label, group: c.state === "due_later" ? groupFor(c.dueAt, now) : c.state === "overdue" ? "now" : "today", action: "Review note", sourceId: u.id });
      continue;
    }
    push({ id: `unsigned:${u.id}`, kind: "unsigned", patientId: u.patient.id, patientName: name, label: "Visit needs a note", dueAt: u.date, action: "Write note" });
  }
  // §Batch C3 — overdue crisis notes escalate to the clinical coordinator pool.
  if (isCoordinatorRole(actor.role)) for (const { patient, note, clock } of overdueCrisisNotes(patients, now))
    rows.push({ id: `crisis_note:${note.id}`, kind: "crisis_note", patientId: patient.id, patientName: `${patient.firstName} ${patient.lastName}`, label: "Crisis note overdue — escalated", dueAt: clock.dueAt, due: clock.label, group: "now", action: "Open chart", sourceId: note.id });
  for (const { patient, note } of AdelanteEHR.listNotesAwaitingCosign().filter(({ note }) => !note.cosignOwnerOverrideId || aliases.has(note.cosignOwnerOverrideId)))
    if (mineIds.has(patient.id) || (!!note.cosignOwnerOverrideId && aliases.has(note.cosignOwnerOverrideId))) push({ id: `cosign:${note.id}`, kind: "cosign", patientId: patient.id, patientName: `${patient.firstName} ${patient.lastName}`, label: "Cosign note", dueAt: note.signedAt ?? note.date, action: "Review" });
  for (const r of myPendingRefills(actor)) {
    const patient = AdelanteEHR.getPatient(r.patientId);
    if (!patient || filterSudMedsForRole([{ medicationName: r.refill.medicationName }], actor.role, patient).visible.length === 0) continue;
    push({ id: `refill:${r.refill.id}`, kind: "refill", patientId: r.patientId, patientName: r.patientName, label: `Refill — ${r.refill.medicationName}`, dueAt: r.refill.requestedAt, action: "Review refill" });
  }
  // §Batch C4 — named owner sees it on top with a countdown; pool items go to
  // coordinators; overdue named items also appear for coordinators to reassign.
  for (const c of AdelanteEHR.listOpenCrisisEscalations()) {
    const e = c.escalation;
    const sla = crisisSlaState(e, +now);
    const owned = !!e.ownerStaffId && aliases.has(e.ownerStaffId);
    const pool = e.ownerLane !== "named";
    const coord = isCoordinatorRole(actor.role);
    if (!(owned || (coord && (pool || sla.overdue)) || (!e.ownerStaffId && mineIds.has(c.patient.id)))) continue;
    const left = Math.max(0, crisisSlaTarget(e).ms - sla.ageMs);
    const countdown = sla.overdue ? overdueByLabel(sla.overdueByMs) : (({ h, m }) => `${h}h ${m}m left`)(hoursMinutesLeft(left));
    const label = owned ? "Crisis follow-up — yours" : pool ? "Crisis follow-up — coordinator pool" : `Crisis follow-up needed — owner ${e.ownerName ?? "assigned"}`;
    rows.push({ id: `crisis:${e.id}`, kind: "crisis", patientId: c.patient.id, patientName: `${c.patient.firstName} ${c.patient.lastName}`, label, dueAt: e.lastTriggeredAt ?? e.triggeredAt, due: countdown, group: "now", action: coord && !owned ? "Reassign" : "Open crisis", sourceId: e.id });
  }
  if (!rescreenTileRole(actor.role)) for (const r of screenerDueRows(mine, { role: actor.role }))
    push({ id: `screener:${r.patientId}:${r.screenerKey}`, kind: "screener", patientId: r.patientId, patientName: r.patientName, label: `${r.screenerKey.toUpperCase()} re-screen`, dueAt: now.toISOString(), action: r.taskAlreadySent ? "Open chart" : "Send re-screen", sourceId: r.screenerKey });
  for (const r of asamTaskRows(actor.role, now) ?? []) {
    if (!mineIds.has(r.patientId)) continue;
    push({ id: `asam:${r.taskId}`, kind: "asam", patientId: r.patientId, patientName: r.patientName, label: "ASAM assessment", dueAt: r.dueDate, action: "Open ASAM", sourceId: r.taskId });
  }
  for (const r of myPendingLabs(actor, actor.role))
    push({ id: `lab:${r.id}`, kind: "lab", patientId: r.patientId, patientName: r.patientName, label: `${r.label} result`, dueAt: r.dueAt, action: "Review lab" });
  for (const r of myPlanReviewsDue(actor, now))
    push({ id: `plan:${r.patientId}`, kind: "plan", patientId: r.patientId, patientName: r.patientName, label: "Care plan review", dueAt: r.dueAt, action: "Review plan" });
  for (const r of hieFollowUps([...mineIds], actor.role)) {
    const p = AdelanteEHR.getPatient(r.encounter.patientId);
    push({ id: `outside:${r.draft.id}`, kind: "outside", patientId: r.encounter.patientId, patientName: p ? `${p.firstName} ${p.lastName}` : "Patient", label: "Outside event follow-up", dueAt: r.encounter.at, action: "Review event" });
  }
  for (const s of actor.clinicianId ? AdelanteEHR.listProviderSwitches({ clinicianId: actor.clinicianId, role: "outgoing", status: "pending_review" }) : []) {
    const p = AdelanteEHR.getPatient(s.patientId);
    push({ id: `switch:${s.id}`, kind: "switch", patientId: s.patientId, patientName: p ? `${p.firstName} ${p.lastName}` : "Patient", label: "Provider switch review", dueAt: s.createdAt, action: "Review" });
  }
  // §Batch E — possible duplicates for coordinator / sys_admin. Label stays generic.
  if (isCoordinatorRole(actor.role)) for (const r of listMatchReviews("open")) {
    const pid = r.newPatientId ?? r.existingPatientId;
    const p = AdelanteEHR.getPatient(pid);
    push({ id: `match:${r.id}`, kind: "match", patientId: pid, patientName: p ? `${p.firstName} ${p.lastName}` : "Patient", label: r.kind === "signup_attempt" ? "Sign-up matched an existing record" : "Possible duplicate record", dueAt: r.createdAt, action: "Review match", sourceId: r.id });
  }
  if (isCareRole(actor.role)) for (const r of myContactsDue(actor.staffId, now))
    push({ id: `contact:${r.patient.id}`, kind: "contact", patientId: r.patient.id, patientName: `${r.patient.firstName} ${r.patient.lastName}`, label: "Contact due", dueAt: now.toISOString(), action: "Log contact" });
  for (const t of AdelanteEHR.listCaseTasks().filter((t) => t.status !== "done" && (!t.snoozedUntil || +new Date(t.snoozedUntil) <= +now) && (aliases.has(t.assignedTo) || mineIds.has(t.patientId)) && (inFacilityEnabled() || !isInFacilityTask(t)))) {
    const p = AdelanteEHR.getPatient(t.patientId);
    if (/asam|caloms|sud/i.test(t.taskType ?? "") && (!p || !roleSeesAsamSection(actor.role, p))) continue;
    if (t.allowedRoles?.length && !t.allowedRoles.includes(actor.role)) continue;
    push({ id: `task:${t.id}`, kind: "task", patientId: t.patientId, patientName: p ? `${p.firstName} ${p.lastName}` : "Patient", label: t.title, dueAt: t.dueDate, action: "Open task", sourceId: t.id });
  }
  // §Batch B2 — referral chase tasks (owner, or coordinator pool). Neutral text only.
  for (const c of chaseRowsFor(actor, now))
    push({ id: `chase:${c.referral.id}`, kind: "chase", patientId: c.referral.enrolledPatientId ?? "", patientName: `${c.referral.firstName} ${c.referral.lastName} (referral)`, label: `${c.lane === "pool" ? (c.task.owner ? "Follow-up needed — reassign · " : "Unassigned · ") : ""}${c.text}`, dueAt: c.task.dueAt, action: c.lane === "pool" && !c.task.owner ? "Claim" : "Open referral", sourceId: c.referral.id });
  // §C3 — re-screen severity flags go to the patient's assigned clinician. Neutral label.
  for (const p of patients) {
    const who = severityAssignee(p);
    if (!who || !aliases.has(who)) continue;
    for (const f of openSeverityFlags(p, actor.role))
      rows.push({ id: `severity:${f.id}`, kind: "severity", patientId: p.id, patientName: `${p.firstName} ${p.lastName}`, label: `${SEVERITY_ROW_LABEL} — ${f.text}`, dueAt: f.createdAt, due: "Review", group: "now", action: "Review", sourceId: f.id });
  }
  // §U1 — my other escalations (handed to me, missed handoffs, social needs) not already listed above.
  const listed = new Set(rows.map((r) => r.sourceId).filter(Boolean));
  for (const e of myOpenEscalations({ role: actor.role, staffId: actor.staffId }, +now)) {
    if (listed.has(e.sourceId)) continue;
    rows.push({ id: `escalation:${e.key}`, kind: "escalation", patientId: e.patientId, patientName: e.patientName, label: `${e.typeLabel} — escalation`, dueAt: e.dueAt, due: e.countdown, group: "now", action: "Open escalations", sourceId: e.key });
  }
  // §Calendars L4/L5 — coordinator items: authors out with notes waiting, and
  // booked visits hit by a new closed day / time off. Neutral text, no type.
  if (isCoordinatorRole(actor.role)) {
    for (const a of authorOutItems(patients, now))
      rows.push({ id: `author_out:${a.authorId}`, kind: "author_out", patientId: "", patientName: a.authorName, label: `${AUTHOR_OUT_LABEL} (${a.openNotes}) · out ${a.outFrom}${a.outTo !== a.outFrom ? ` – ${a.outTo}` : ""}`, dueAt: now.toISOString(), due: "Reassign or arrange a cosigner", group: "today", action: "Open team calendar", sourceId: a.authorId });
    for (const r of listRescheduleItems("open")) {
      const p = patients.find((x) => x.id === r.patientId);
      rows.push({ id: `reschedule:${r.id}`, kind: "reschedule", patientId: r.patientId, patientName: p ? `${p.firstName} ${p.lastName}` : "Patient", label: `Reschedule needed — ${r.cause === "site_closed" ? "clinic closed" : "clinician out"}`, dueAt: r.start, due: new Date(r.start).toLocaleDateString("en-US", { month: "short", day: "numeric" }), group: "today", action: "Mark handled", sourceId: r.id });
    }
  }
  // §B1 — MAT refill needed / missed dose → prescriber (pool → coordinator). Part 2-masked label.
  for (const a of continuityTasks(now)) {
    const mineRow = a.ownerStaffId ? aliases.has(a.ownerStaffId) : isCoordinatorRole(actor.role);
    if (!mineRow) continue;
    const p = patients.find((x) => x.id === a.patientId);
    const label = p && roleSeesAsamSection(actor.role, p) ? continuityTaskLabel(a) : NEUTRAL_TYPE_LABEL;
    rows.push({ id: `continuity:${a.key}`, kind: "continuity", patientId: a.patientId, patientName: a.patientName, label, dueAt: a.dueAt, due: "Same business day (Draft)", group: "today", action: "Open chart", sourceId: a.key });
  }
  // §B2 — 30 days before release, nothing submitted → CF care manager / ECM (pool → coordinator).
  for (const r of releaseCoverageRows(now)) {
    if (!r.task) continue;
    if (!(r.ownerStaffId ? aliases.has(r.ownerStaffId) : isCoordinatorRole(actor.role))) continue;
    rows.push({ id: `coverage:${r.episodeId}`, kind: "coverage", patientId: r.patientId, patientName: r.patientName, label: `Medi-Cal not submitted — ${dayOffsetLabel(r.dayOffset)}`, dueAt: releaseCoverageDueAt(r, now), due: "Draft", group: "week", action: "Open coverage", sourceId: r.episodeId });
  }
  // §B6 — deactivated staff still owning open items: one item each, counts only.
  if (isCoordinatorRole(actor.role)) for (const r of reassignNeededItems()) {
    const c = r.counts;
    rows.push({ id: `reassign_needed:${r.staffId}`, kind: "reassign_needed", patientId: "", patientName: r.name, label: `Reassign needed — ${c.notesToSign} notes to sign · ${c.tasks} tasks · ${c.escalations} escalations · ${c.caseload} caseload`, dueAt: now.toISOString(), due: "Nothing reassigned automatically", group: "today", action: "Open staff", sourceId: r.staffId });
  }
  // §U2 — @mentions in team threads: "Reply needed" until replied or marked done.
  const myThreads = listThreadsFor({ staffId: actor.staffId, role: actor.role });
  for (const m of openMentionsFor(actor.staffId)) {
    const t = myThreads.find((x) => x.id === m.threadId);
    if (!t) continue;
    const p = t.patientId ? patients.find((x) => x.id === t.patientId) : undefined;
    rows.push({ id: `reply:${m.id}`, kind: "reply", patientId: t.patientId ?? "", patientName: p ? `${p.firstName} ${p.lastName}` : "Team thread", label: "Reply needed — team thread", dueAt: m.createdAt, due: "Reply", group: "now", action: "Reply", sourceId: m.id });
  }
  // §Access A3 — restricted-record opens → compliance stand-in (credentialing coordinator).
  if (actor.role === "credentialing_coordinator") for (const i of listRestrictedOpenItems())
    rows.push({ id: `restricted_open:${i.id}`, kind: "restricted_open", patientId: "", patientName: i.actorName, label: "Restricted record opened", dueAt: i.at, due: "Review", group: "today", action: "Open Quality & compliance", sourceId: i.id });
  // §A3 — county report reminders (Draft owner: billing coordinator).
  for (const r of countyReminders(actor.role, now))
    rows.push({ id: `county:${r.id}`, kind: "county_reminder", patientId: "", patientName: "County reporting", label: r.label, dueAt: r.due, due: r.kind === "1_day" ? "1 day" : "5 days", group: "week", action: "Open county reporting", sourceId: r.id });
  // §Group 1 C2 / B4 — a care-plan flag with no live journey → its content owner (named content_authoring owner, else owner pool). Neutral, counts only.
  for (const g of listContentGaps()) if (isContentGapOwner(g, actor))
    rows.push({ id: contentGapKey(g.id), kind: "content_gap", patientId: "", patientName: "Patient content", label: `${CONTENT_GAP_LABEL} (${g.patients < 11 ? "fewer than 11" : g.patients} patients)`, dueAt: g.at, due: "Draft", group: "week", action: "Open content center", sourceId: g.id });
  // §A3 — content waiting for a clinical reviewer.
  if (CONTENT_REVIEWER_ROLES.includes(actor.role)) for (const e of contentReviewQueue().filter((x) => contentVisibleToStaff(actor.role, x.typeId, x.body)))
    rows.push({ id: `content-waiting:${e.typeId}:${e.id}`, kind: "content_waiting", patientId: "", patientName: "Patient content", label: `Content review waiting — ${contentType(e.typeId).titleOf(e.body)}`, dueAt: now.toISOString(), due: "Review", group: "week", action: "Review content", sourceId: e.id });
  for (const e of staleContentFor(actor.staffId ?? "", actor.staffName, actor.role, now)) rows.push({ id: `content-review:${e.typeId}:${e.id}`, kind: "content_review", patientId: "", patientName: "Patient content", label: `Review follow-up needed — ${contentType(e.typeId).titleOf(e.body)}`, dueAt: now.toISOString(), due: "Past review date", group: "today", action: "Review content", sourceId: e.id });
  // Crisis always first, crisis notes pinned right after (top of Needs closing).
  const priority = isPrescriberRole(actor.role) ? ["crisis", "crisis_note", "severity", "escalation", "reply", "refill"] : isCareRole(actor.role) ? ["crisis", "crisis_note", "severity", "escalation", "reply", "contact"] : ["crisis", "crisis_note", "severity", "escalation", "reply"];
  return rows.filter((r, i, all) => all.findIndex((x) => x.id === r.id) === i).sort((a, b) => {
    const ai = priority.indexOf(a.kind), bi = priority.indexOf(b.kind);
    if (ai !== bi) return (ai < 0 ? 99 : ai) - (bi < 0 ? 99 : bi);
    return a.dueAt.localeCompare(b.dueAt);
  });
}

export function attentionCaseload(actor: ActingIdentity & { role: StaffRole }, rows: WorkspaceActionRow[]) {
  const byPatient = new Map<string, WorkspaceActionRow[]>();
  // R53 part 2 — screener rows moved to the Re-screens due tile; caseload badges keep them.
  const now = new Date();
  const badges = rescreenTileRole(actor.role) ? [...rows, ...screenerDueRows(myCaseload(actor), { role: actor.role }).map((r): WorkspaceActionRow => ({ id: `screener:${r.patientId}:${r.screenerKey}`, kind: "screener", patientId: r.patientId, patientName: r.patientName, label: `${r.screenerKey.toUpperCase()} re-screen`, dueAt: now.toISOString(), group: groupFor(now.toISOString(), now), due: dueText(now.toISOString(), now), action: r.taskAlreadySent ? "Open chart" : "Send re-screen", sourceId: r.screenerKey }))] : rows;
  for (const r of badges) byPatient.set(r.patientId, [...(byPatient.get(r.patientId) ?? []), r]);
  return myCaseload(actor).map((patient) => ({ patient, reasons: byPatient.get(patient.id) ?? [] })).sort((a, b) => b.reasons.length - a.reasons.length || a.patient.lastName.localeCompare(b.patient.lastName));
}

/** Part 2-safe closed loop: operational copy only, with a stable dedupe key. */
export function notifyNeedsClosing(actor: ActingIdentity & { role: StaffRole }, visits: Appointment[], now = new Date()) {
  for (const a of visits) {
    const end = +new Date(a.start) + a.durationMin * 60000;
    AdelanteEHR.notify({ recipientStaffId: actor.staffId, category: "task_assigned", subject: "Visit needs closing", body: "A past visit needs a status or note. Open your workspace.", patientId: a.patientId, linkRoute: "/clinician", dedupeKey: `needs-closing:${a.id}` });
    if (+now - end < 86400000) continue;
    const supervisor = STAFF_ROSTER.find((s) => s.id === STAFF_ROSTER.find((s) => s.id === actor.staffId)?.supervisedBy);
    if (supervisor) AdelanteEHR.notify({ recipientStaffId: supervisor.id, category: "task_assigned", subject: "Visit remains open", body: "A supervised clinician has a visit still open after 24 hours.", patientId: a.patientId, linkRoute: "/clinician", dedupeKey: `needs-closing-escalated:${a.id}` });
    else AdelanteEHR.notify({ recipientRole: "clinical_coordinator", category: "task_assigned", subject: "Visit remains open", body: "A clinician visit is still open after 24 hours.", patientId: a.patientId, linkRoute: "/clinician", dedupeKey: `needs-closing-escalated:${a.id}` });
  }
}

