export function ProviderHistoryTab({ patientId }: { patientId: string }) {
  const switches = useEhr(() => AdelanteEHR.listProviderSwitches({ patientId, status: "any" }));
  const clinicians = AdelanteEHR.listClinicians();
  const patient = useEhr(() => AdelanteEHR.getPatient(patientId));
  const { role, staffName, clinicianId } = useActingStaff();
  const [noteFor, setNoteFor] = useState<string | null>(null);
  const [note, setNote] = useState("");
  const canWrite = patient
    ? canAccess(role, "care_coordination", patient).level === "write"
    : false;
  const nameFor = (id: string) => clinicians.find((c) => c.id === id)?.name ?? id;
  const reasonLabel: Record<string, string> = {
    reschedule: "Reschedule",
    new_appointment: "New booking",
    refill_review: "Refill review",
    primary_reassignment: "Primary reassignment",
  };
  if (switches.length === 0) {
    return (
      <div className="text-sm text-muted-foreground">
        No provider switches recorded for this client.
      </div>
    );
  }
  return (
    <ul className="space-y-2">
      {switches.map((s) => {
        // Per-record authorization: only the outgoing provider this alert is
        // addressed to may resolve it — role-level write is necessary but
        // not sufficient.
        const isAddressee = Boolean(clinicianId && clinicianId === s.fromClinicianId);
        const actionable = s.status === "pending_review";
        return (
          <li key={s.id} className="rounded border p-3 text-sm">
            <div className="flex items-center justify-between gap-2">
              <div className="font-medium text-navy">
                {nameFor(s.fromClinicianId)} to {nameFor(s.toClinicianId)}
              </div>
              <StatusChip lang="en" state={s.status === "acknowledged" ? "done" : s.status === "pending_review" ? (isAddressee ? "yourturn" : "team") : "closed"} label={s.status.replace("_", " ")} />
            </div>
            <div className="mt-1 text-xs text-muted-foreground">
              {reasonLabel[s.reason] ?? s.reason}
              {s.serviceType ? ` · ${s.serviceType}` : ""}
              {" · "}
              {new Date(s.createdAt).toLocaleString()}
            </div>
            {s.context ? <div className="mt-1 text-xs">{s.context}</div> : null}
            {s.resolutionNote ? (
              <div className="mt-1 text-xs text-muted-foreground italic">
                Note: {s.resolutionNote}
              </div>
            ) : null}
            {s.resolvedBy ? (
              <div className="mt-1 text-[10px] text-muted-foreground">
                Resolved by {nameFor(s.resolvedBy)}
              </div>
            ) : null}
            {actionable &&
              (canWrite && isAddressee ? (
                <div className="mt-2 space-y-2">
                  {noteFor === s.id && (
                    <Textarea
                      rows={2}
                      className="text-xs"
                      placeholder="Hand-off / coordination note (optional)"
                      value={note}
                      onChange={(e) => setNote(e.target.value)}
                    />
                  )}
                  <div className="flex flex-wrap gap-2">
                    <Button
                      size="sm"
                      variant="outline"
                      className="h-7 text-[11px]"
                      onClick={() => {
                        AdelanteEHR.acknowledgeProviderSwitch(
                          s.id,
                          s.fromClinicianId,
                          note.trim() || undefined,
                        );
                        setNote("");
                        setNoteFor(null);
                        toast.success(`Switch acknowledged by ${staffName}`);
                      }}
                    >
                      Acknowledge
                    </Button>
                    <Button
                      size="sm"
                      variant="ghost"
                      className="h-7 text-[11px]"
                      onClick={() => {
                        AdelanteEHR.dismissProviderSwitch(
                          s.id,
                          s.fromClinicianId,
                          note.trim() || undefined,
                        );
                        setNote("");
                        setNoteFor(null);
                        toast("Alert dismissed");
                      }}
                    >
                      Don't use this draft
                    </Button>
                    {noteFor !== s.id && (
                      <Button
                        size="sm"
                        variant="ghost"
                        className="h-7 text-[11px]"
                        onClick={() => setNoteFor(s.id)}
                      >
                        Add note
                      </Button>
                    )}
                  </div>
                </div>
              ) : (
                <div className="mt-2 inline-flex items-center gap-1 text-[11px] text-muted-foreground">
                  <Lock className="h-3 w-3" />
                  {canWrite
                    ? `Only ${nameFor(s.fromClinicianId)} can resolve this hand-off.`
                    : "Your role cannot resolve provider switches."}
                </div>
              ))}
          </li>
        );
      })}
    </ul>
  );
}

/**
 * §Crisis Redesign Phase 2 — the SDOH-urgent trigger.
 *
 * Deliberately a manual, reasoned action. Nothing about the need text or its
 * status decides urgency: whether "no place to sleep tonight" is a crisis is a
 * human judgement, so a staff member states why and owns it.
 */
function FlagSdohUrgentControl({
  patientId,
  item,
  escalationOpen,
}: {
  patientId: string;
  item: { id: string; urgentEscalationId?: string; urgentFlaggedAt?: string };
  /**
   * True only while the LINKED escalation is still open. A resolved escalation
   * must not permanently disable re-escalation — the store already allows it
   * (`flagSdohItemUrgent` throws only on an open escalation), so the UI reads
   * the live escalation status rather than the historical flag timestamp.
   */
  escalationOpen: boolean;
}) {
  const { staffName } = useActingStaff();
  const [open, setOpen] = useState(false);
  const [reason, setReason] = useState("");
  if (escalationOpen) return null;
  if (!open)
    return (
      <Button size="sm" variant="outline" onClick={() => setOpen(true)}>
        <ShieldAlert className="mr-1 h-3.5 w-3.5" /> Flag as urgent
      </Button>
    );
  return (
    <div className="space-y-2 rounded border border-destructive/40 bg-destructive/5 p-2">
      <p className="text-[11px] text-muted-foreground">
        This puts the need in the urgent social needs lane of the crisis queue, routed to case
        management. Say why it cannot wait.
      </p>
      <Textarea
        rows={2}
        value={reason}
        onChange={(e) => setReason(e.target.value)}
        aria-label="Why this social need is urgent"
        placeholder="e.g. Loses shelter bed tonight; no other placement."
      />
      <div className="flex gap-2">
        <Button
          size="sm"
          variant="destructive"
          disabled={reason.trim().length < 3}
          onClick={() => {
            try {
              AdelanteEHR.flagSdohItemUrgent(patientId, item.id, staffName, reason);
              toast.success("Flagged urgent — it is now in the urgent social needs lane.");
              setOpen(false);
              setReason("");
            } catch (e) {
              toast.error(e instanceof Error ? e.message : "Could not flag this need.");
            }
          }}
        >
          Flag urgent
        </Button>
        <Button size="sm" variant="ghost" onClick={() => setOpen(false)}>
          Cancel
        </Button>
      </div>
    </div>
  );
}

