            }}
          >
            <Plus className="h-4 w-4 mr-1" /> Add
          </Button>
        </Card>
      )}
      <ul className="space-y-2">
        {items.length === 0 && (
          <li className="text-xs text-muted-foreground">No SDOH items logged.</li>
        )}
        {items.map((i) => (
          <li key={i.id} className="rounded border p-3 space-y-2 text-sm">
            <div className="flex items-start justify-between gap-2">
              <div className="font-medium text-navy">
                {i.need}
                {i.visibleToPatient === false && (
                  <Badge variant="outline" className="ml-2 text-[10px]">
                    Staff only
                  </Badge>
                )}
              </div>
              <StatusChip lang="en" state={i.status === "completed" ? "done" : i.status === "identified" || i.status === "not_completed" ? (i.createdBy === staffName || i.createdByRole === role ? "yourturn" : "team") : "team"} label={i.status.replace("_", " ")} />
            </div>
            <div className="flex flex-wrap gap-1.5 text-[10px]" data-testid="staff-need-meta">
              <Badge variant="outline" className="text-[10px]">
                Category: {categoryName(i.categoryId ?? matchResourcesForNeed(i)?.categoryIds[0]) ?? "—"}
              </Badge>
              <Badge variant="outline" className="text-[10px]">{(_SRC ?? {})[i.source]}</Badge>
              {i.urgency && (
                <Badge variant={i.urgency === "today" ? "outline" : "outline"} className="text-[10px]">
                  Urgency: {URGENCY_LABEL.en[i.urgency]}
                </Badge>
              )}
            </div>
            <NeedReferralList patientId={patientId} itemId={i.id} />
            <NeedAgingLine patientId={patientId} item={i} />
            <SdohActivityLog
              patientId={patientId}
              target="need"
              targetId={i.id}
              {...(i.log ? { log: i.log } : {})}
              {...(i.note ? { legacyNote: i.note } : {})}
              readOnly={readOnly}
            />
            <AttributionLine
              {...(i.createdBy ? { createdBy: i.createdBy, createdAt: i.createdAt } : {})}
              {...(i.lastUpdatedBy
                ? {
                    updatedBy: i.lastUpdatedBy,
                    ...(i.updatedAt ? { updatedAt: i.updatedAt } : {}),
                  }
                : {})}
            />

            {i.urgentFlaggedAt &&
              (urgentOpen(i.urgentEscalationId) ? (
                <div className="text-[11px] text-destructive">
                  Flagged urgent by {i.urgentFlaggedBy} · <ClientDate value={i.urgentFlaggedAt} /> —
                  open in the urgent social needs lane of the crisis queue.
                </div>
              ) : (
                <div className="text-[11px] text-muted-foreground">
                  Previously flagged urgent by {i.urgentFlaggedBy} ·{" "}
                  <ClientDate value={i.urgentFlaggedAt} /> — that escalation is resolved. Flag again
                  if it is urgent now.
                </div>
              ))}
            {!readOnly && (
              <FlagSdohUrgentControl
                patientId={patientId}
                item={i}
                escalationOpen={urgentOpen(i.urgentEscalationId)}
              />
            )}
            {!readOnly && (
              <div className="flex flex-wrap items-center gap-2">
                <Button size="sm" variant="outline" onClick={() => setReferItem(i)}>
                  <Building2 className="h-3.5 w-3.5 mr-1" /> Refer
                </Button>
                <Select
                  value={i.status}
                  onValueChange={(v) =>
                    AdelanteEHR.setSdohStatus(patientId, i.id, v as SdohStatus, undefined, {
                      staffName,
                      role,
                    })
                  }


                >
                  <SelectTrigger className="h-8 text-xs w-[160px]">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {statusOpts.map((s) => (
                      <SelectItem key={s} value={s} className="capitalize">
                        {s.replace("_", " ")}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <Button
                  size="sm"
                  variant="ghost"
                  onClick={() => {
                    // §5d-2 — turning a safety need ON for the patient is a
                    // risk decision, so it asks first. Turning it off never does.
                    if (i.safetySensitive && i.visibleToPatient === false) {
                      setSafetyReveal(i);
                      return;
                    }
                    AdelanteEHR.setSdohVisibility(patientId, i.id, !i.visibleToPatient);
                  }}
                >
                  {i.visibleToPatient ? (
                    <>
                      <Eye className="h-3.5 w-3.5 mr-1" /> Visible
                    </>
                  ) : (
                    <>
                      <EyeOff className="h-3.5 w-3.5 mr-1" /> Hidden
                    </>
                  )}
                </Button>
                <Button
                  size="sm"
                  variant="ghost"
                  onClick={() => AdelanteEHR.removeSdohItem(patientId, i.id)}
                >
                  <Trash2 className="h-3.5 w-3.5" />
                </Button>
              </div>
            )}
          </li>
        ))}
      </ul>
      {referItem && (
        <ReferForNeedDialog
          patientId={patientId}
          item={referItem}
          open
          onOpenChange={(v) => !v && setReferItem(null)}
        />
      )}
      <AlertDialog open={Boolean(safetyReveal)} onOpenChange={(v) => !v && setSafetyReveal(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Show this safety need to the patient?</AlertDialogTitle>
            <AlertDialogDescription>
              Someone who has disclosed interpersonal safety risk may be living with the person
              harming them. Making this visible puts it on their portal and their phone, and shares
              it with an authorized advocate. Only do this if you have talked it through with them.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep staff only</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => {
                if (safetyReveal) AdelanteEHR.setSdohVisibility(patientId, safetyReveal.id, true);
                setSafetyReveal(null);
              }}
            >
              Make visible
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

/**
 * §5d-2 — the referrals made for one need, read through the single lookup.
 * Directory link state is shown honestly: an org that has been unpublished
 * still names the referral, flagged as no longer listed.
 */
/**
 * §5d-3 — draft aging read. Nothing is stamped: this is elapsed time since the
 * last real action, including an activity-log entry.
 */
function NeedAgingLine({ patientId, item }: { patientId: string; item: SdohPlanItem }) {
  const count = useEhr(() => AdelanteEHR.referralsForNeed(patientId, item.id).length);
  const aging = sdohNeedAging(item, count);
  if (aging.state !== "due" && aging.state !== "overdue") return null;
  return (
    <div
      className={`text-[11px] ${aging.state === "overdue" ? "text-attention" : "text-muted-foreground"}`}
    >
      {sdohAgingLabel(aging)} · {SDOH_AGING_DRAFT.label}
    </div>
  );
}

function NeedReferralList({ patientId, itemId }: { patientId: string; itemId: string }) {
  const json = useEhr(() => JSON.stringify(AdelanteEHR.referralsForNeed(patientId, itemId)));
  const refs = JSON.parse(json) as ResourceReferral[];
  if (refs.length === 0) return null;
  return (
    <ul className="space-y-1">
      {refs.map((r) => {
        const link = resourceLinkState(r);
        return (
          <li key={r.id} className="text-xs text-muted-foreground flex flex-wrap items-center gap-1.5">
            <Building2 className="h-3 w-3" />
            <span className="text-navy">{referralProviderLabel(r)}</span>
            <Badge variant="outline" className="text-[10px]">
              {RESOURCE_REFERRAL_OUTCOME_LABEL[r.status]}
            </Badge>
            {link.kind === "external" && <span>Not in the directory</span>}
            {link.kind === "inactive" && <span>Directory listing not published</span>}
            {link.kind === "missing" && <span>No longer in the directory</span>}
            {!isReferralOpen(r) && <span>· closed</span>}
          </li>
        );
      })}
    </ul>
  );
}

/**
 * §5d-1 — attribution line shown inline on needs and referrals.
 */
function AttributionLine({
  createdBy,
  createdAt,
  updatedBy,
  updatedAt,
}: {
  createdBy?: string;
  createdAt?: string;
  updatedBy?: string;
  updatedAt?: string;
}) {
  if (!createdBy && !updatedBy) return null;
  return (
    <div className="text-[11px] text-muted-foreground">
      {createdBy && (
        <span>
          Added by {createdBy}
          {createdAt && (
            <>
              {" · "}
              <ClientDate value={createdAt} />
            </>
          )}
        </span>
      )}
      {createdBy && updatedBy && " — "}
      {updatedBy && (
        <span>
          Updated by {updatedBy}
          {updatedAt && (
            <>
              {" · "}
              <ClientDate value={updatedAt} />
            </>
          )}
        </span>
      )}
    </div>
  );
}

export function ReferralsTab({
  patientId,
  sudGated,
  readOnly,
}: {
  patientId: string;
  sudGated: boolean;
  readOnly?: boolean;
}) {
  const p = useEhr(() => AdelanteEHR.getPatient(patientId));
  const { staffName, role } = useActingStaff();
  const items = p?.resourceReferrals ?? [];
  const [category, setCategory] = useState<ResourceReferral["category"]>("housing");
  const [provider, setProvider] = useState("");
  const [note, setNote] = useState("");
  // §5d-2 — a resolve PROMPT, never an auto-close: a human decides whether the
  // need is met.
  const [resolvePrompt, setResolvePrompt] = useState<ResourceReferral | null>(null);
  return (
    <div className="space-y-3">
      {!readOnly && (
        <Card className="p-3 space-y-2">
          <div className="text-xs uppercase tracking-wider text-muted-foreground">New referral</div>
          <div className="grid grid-cols-2 gap-2">
            <Select value={category} onValueChange={(v) => setCategory(v as typeof category)}>
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {RESOURCE_CATEGORIES.map((c) => (
                  <SelectItem key={c.id} value={c.id}>
                    {c.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            <Input
              placeholder="Provider"
              value={provider}
              onChange={(e) => setProvider(e.target.value)}
            />
          </div>
          {isPart2SensitiveCategory(category) && (
            <div className="text-[11px] text-muted-foreground flex items-start gap-1.5">
              <Lock className="h-3 w-3 mt-0.5 text-teal" />
              This category can disclose SUD treatment status. It needs the patient&apos;s 42 CFR
              Part 2 consent on file.
            </div>
          )}
          <Textarea
            rows={2}
            placeholder="Note (optional)"
            value={note}
            onChange={(e) => setNote(e.target.value)}
          />
          <Button
            size="sm"
            onClick={() => {
              if (!provider.trim()) return toast.error("Add a provider");
              try {
                // The data layer stamps `sudDisclosureConsent` from the patient's
                // live consent and refuses Part 2 categories without it.
                act("sdoh_referral", "addResourceReferral",
                  patientId,
                  { category, provider, note, visibleToPatient: true },
                  { staffName, role },
                );
                setProvider("");
                setNote("");
                toast.success("Referral created");
              } catch (e) {
                toast.error(e instanceof Error ? e.message : "Could not create this referral.", {
                  action: {
                    label: "Open consents",
                    onClick: () => {
                      window.location.assign(`/record/${patientId}?section=consents`);
                    },
                  },
                });
              }
            }}
          >
            Create referral
          </Button>
        </Card>
      )}
      <ul className="space-y-2">
        {items.length === 0 && <li className="text-xs text-muted-foreground">No referrals yet.</li>}
        {items.map((r) => {
          // §5d-1 — for a Part 2 gated viewer the CATEGORY is itself the
          // sensitive fact, so the row carries no category, provider, note or
          // category styling: existence and nothing else.
          const masked = sudGated && isPart2SensitiveCategory(r.category);
          if (masked) {
            return (
              <li
                key={r.id}
                className="rounded border border-dashed p-3 text-sm text-muted-foreground flex items-start gap-2"
              >
                <Lock className="h-3.5 w-3.5 mt-0.5" />
                <div>
                  <div>Restricted referral — 42 CFR Part 2 consent required.</div>
                  <div className="text-[11px]">
                    Created <ClientDate value={r.createdAt} />
                  </div>
                </div>
              </li>
            );
          }
          return (
            <li key={r.id} className="rounded border p-3 text-sm space-y-2">
              <div className="flex items-start justify-between gap-2">
                <div>
                  <div className="capitalize text-navy">
                    {r.category} · {referralProviderLabel(r)}
                  </div>
                  <div className="text-[11px] text-muted-foreground">
                    Created <ClientDate value={r.createdAt} />
                    {(() => {
                      const link = resourceLinkState(r);
                      if (link.kind === "external") return " · not in the directory";
                      if (link.kind === "inactive") return " · directory listing not published";
                      if (link.kind === "missing") return " · no longer in the directory";
                      return " · directory listing";
                    })()}
                  </div>
                  {r.sdohItemId && (
                    <div className="text-[11px] text-muted-foreground">
                      For need:{" "}
                      {(p?.sdohPlan?.items ?? []).find((i) => i.id === r.sdohItemId)?.need ??
                        "need no longer on file"}
                    </div>
                  )}
                  {r.outcomeReason && (
                    <div className="text-[11px] text-muted-foreground">
                      Outcome reason: {r.outcomeReason}
                    </div>
                  )}
                </div>
                <Badge variant="outline" className="text-[10px]">
                  {RESOURCE_REFERRAL_OUTCOME_LABEL[r.status]}
                </Badge>
              </div>
              {(() => {
                const aging = referralAgingState(r);
                if (aging.state !== "due" && aging.state !== "overdue") return null;
                return (
                  <div
                    className={`text-[11px] ${aging.state === "overdue" ? "text-attention" : "text-muted-foreground"}`}
                  >
                    {sdohAgingLabel(aging)} · {SDOH_AGING_DRAFT.label}
                  </div>
                );
              })()}
              <ReferralFollowUpControl patientId={patientId} referral={r} readOnly={readOnly} />
              <SdohActivityLog
                patientId={patientId}
                target="referral"
                targetId={r.id}
                {...(r.log ? { log: r.log } : {})}
                {...(r.note ? { legacyNote: r.note } : {})}
                readOnly={Boolean(readOnly)}
              />
              <AttributionLine
                {...(r.createdBy ? { createdBy: r.createdBy, createdAt: r.createdAt } : {})}
                {...(r.lastUpdatedBy
                  ? {
                      updatedBy: r.lastUpdatedBy,
                      ...(r.updatedAt ? { updatedAt: r.updatedAt } : {}),
                    }
                  : {})}
              />
              <div className="flex flex-wrap items-center gap-2">
                <ReferralOutcomeControl
                  patientId={patientId}
                  referral={r}
                  onConnected={() => r.sdohItemId && setResolvePrompt(r)}
                />
                <Button
                  size="sm"
                  variant="ghost"
                  onClick={() =>
                    AdelanteEHR.setResourceReferralVisibility(patientId, r.id, !r.visibleToPatient)
                  }
                >
                  {r.visibleToPatient !== false ? (
                    <>
                      <Eye className="h-3.5 w-3.5 mr-1" /> Visible
                    </>
                  ) : (
                    <>
                      <EyeOff className="h-3.5 w-3.5 mr-1" /> Hidden
                    </>
                  )}
                </Button>
              </div>
            </li>
          );
        })}
      </ul>
      <AlertDialog
        open={Boolean(resolvePrompt)}
        onOpenChange={(v) => !v && setResolvePrompt(null)}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Mark the need resolved?</AlertDialogTitle>
            <AlertDialogDescription>
              This referral is connected. That does not automatically mean the need is met — only
              resolve it if the patient actually has what they needed.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Leave the need open</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => {
                if (resolvePrompt?.sdohItemId) {
                  AdelanteEHR.setSdohStatus(
                    patientId,
                    resolvePrompt.sdohItemId,
                    "completed",
                    undefined,
                    { staffName, role },
                  );
                }
                setResolvePrompt(null);
              }}
            >
              Resolve the need
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

/**
 * §5d-2 — outcome + reason. Any outcome other than pending needs a reason;
 * the data layer refuses without one, so this collects it up front.
 */
/**
 * §5d-3 — the referral's follow-up date, which existed on the record but had
 * no UI. Setting one can create a REAL case task for the patient's case
 * manager; when there is no case manager the reason is stated, never silent.
 */
function ReferralFollowUpControl({
  patientId,
  referral,
  readOnly,
}: {
  patientId: string;
  referral: ResourceReferral;
  readOnly?: boolean;
}) {
  const { staffName, role } = useActingStaff();
  const [date, setDate] = useState(referral.followUpDate ?? "");
  if (readOnly) {
    return referral.followUpDate ? (
      <div className="text-[11px] text-muted-foreground">
        Follow up on {referral.followUpDate}
      </div>
    ) : null;
  }
  return (
    <div className="flex flex-wrap items-center gap-2 text-[11px] text-muted-foreground">
      <span>Follow up</span>
      <Input
        type="date"
        className="h-8 w-40 text-xs"
        value={date}
        onChange={(e) => setDate(e.target.value)}
      />
      <Button
        size="sm"
        variant="outline"
        onClick={() => {
          AdelanteEHR.setReferralFollowUpDate(patientId, referral.id, date || undefined, {
            staffName,
            role,
          });
          toast.success(date ? "Follow-up date saved." : "Follow-up date cleared.");
        }}
      >
        Save date
      </Button>
      <Button
        size="sm"
        variant="ghost"
        disabled={!date}
        onClick={() => {
          const res = AdelanteEHR.createSdohFollowUpTask({
            patientId,
            dueDate: date,
            referralId: referral.id,
          });
          if (!res.created) {
            toast.error(res.reason);
            return;
          }
          toast.success("Follow-up task created for the case manager.");
        }}
      >
        Create task
      </Button>
    </div>
  );
}

function ReferralOutcomeControl({
  patientId,
  referral,
  onConnected,
}: {
  patientId: string;
  referral: ResourceReferral;
  onConnected: () => void;
}) {
  const { staffName, role } = useActingStaff();
  const [pendingOutcome, setPendingOutcome] = useState<ResourceReferralOutcome | null>(null);
  const [reason, setReason] = useState("");

  function apply(outcome: ResourceReferralOutcome, why?: string) {
    try {
      AdelanteEHR.setResourceReferralStatus(patientId, referral.id, outcome, undefined, {
        staffName,
        role,
      }, why);
      setPendingOutcome(null);
      setReason("");
      if (outcome === "connected") onConnected();
    } catch (e) {
      toast.error(e instanceof Error ? e.message : "Could not record this outcome.");
    }
  }

  return (
    <>
      <Select
        value={referral.status}
        onValueChange={(v) => {
          const outcome = v as ResourceReferralOutcome;
          if (outcome === "pending") return apply(outcome);
          setPendingOutcome(outcome);
          setReason(referral.outcomeReason ?? "");
        }}
      >
        <SelectTrigger className="h-8 text-xs w-[170px]">
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          {RESOURCE_REFERRAL_OUTCOMES.map((o) => (
            <SelectItem key={o} value={o}>
              {RESOURCE_REFERRAL_OUTCOME_LABEL[o]}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
      <AlertDialog
        open={Boolean(pendingOutcome)}
        onOpenChange={(v) => !v && setPendingOutcome(null)}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>
              {pendingOutcome ? RESOURCE_REFERRAL_OUTCOME_LABEL[pendingOutcome] : ""} — why?
            </AlertDialogTitle>
            <AlertDialogDescription>
              A short reason so the next person picking this up knows what happened.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <Textarea rows={2} value={reason} onChange={(e) => setReason(e.target.value)} />
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={(e) => {
                if (!reason.trim()) {
                  e.preventDefault();
                  toast.error("Give a short reason for this outcome.");
                  return;
                }
                if (pendingOutcome) apply(pendingOutcome, reason.trim());
              }}
            >
              Record outcome
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}


export function EligibilityTab({ patientId, readOnly }: { patientId: string; readOnly?: boolean }) {
  const p = useEhr(() => AdelanteEHR.getPatient(patientId));
  const acting = useActingStaff();
  const [checkOpen, setCheckOpen] = useState(false);
  if (!p) return null;
  const actor = { actorId: acting.staffName, actorRole: acting.role };
  const cov = p.coverage;
  const notes = p.eligibilityNotes ?? {};
  const log = p.eligibilityFlagLog ?? [];
  const consentPending = AdelanteEHR.ecmConsentCapturePending(patientId);
  const rows: {
    key: Parameters<typeof AdelanteEHR.setEligibilityNote>[1];
    label: string;
    on: boolean;
    toggle: (v: boolean) => void;
  }[] = [
    {
      key: "ecm",
      label: "ECM eligible",
      on: Boolean(cov?.ecmEligible),
      toggle: (v) => AdelanteEHR.setEcmEligible(patientId, v, actor),
    },
    {
      key: "jiReentry",
      label: "JI Reentry (90-day)",
      on: Boolean(cov?.jiReentryFlag),
      toggle: (v) => AdelanteEHR.setJiReentry(patientId, v, actor),
    },
    {
      key: "cs_housing",
      label: "CS: Housing",
      on: Boolean(cov?.communitySupports?.housing),
      toggle: (v) => AdelanteEHR.setCommunitySupport(patientId, "housing", v, actor),
    },
    {
      key: "cs_food",
      label: "CS: Food",
      on: Boolean(cov?.communitySupports?.food),
      toggle: (v) => AdelanteEHR.setCommunitySupport(patientId, "food", v, actor),
    },
    {
      key: "cs_transport",
      label: "CS: Transport",
      on: Boolean(cov?.communitySupports?.transport),
      toggle: (v) => AdelanteEHR.setCommunitySupport(patientId, "transport", v, actor),
    },
  ];
  return (
    <div className="space-y-3">
      <p className="text-xs text-muted-foreground">
        Medi-Cal / CalAIM benefit eligibility. These flags are not patient consent.
      </p>
      <CalaimEligibilityComparison patientId={patientId} />
      {consentPending && (
        <div
          className="rounded border border-amber-300 bg-amber-50 p-3 text-xs text-amber-900"
          data-testid="ecm-consent-prompt"
        >
          Marked ECM-eligible, but ECM information-sharing consent has never been captured. Ask the
          client and record their answer on the Consent tab.
        </div>
      )}
      <CoveragePlansSection patientId={patientId} actor={actor} readOnly={readOnly} />
      <EligibilityHistoryCard patientId={patientId} canCheck={!readOnly} onRecordManual={() => setCheckOpen(true)} />
      <ReportedBenefitsCard patientId={patientId} />
      <PaymentArrangementCard patientId={patientId} />

      {!readOnly && (
        <Card className="p-3">
          <div className="text-xs font-medium uppercase text-muted-foreground">Eligibility actions</div>
          <div className="mt-3 flex flex-wrap gap-2">
            <Button size="sm" variant="outline" onClick={() => setCheckOpen(true)}>
              <CheckCircle2 className="h-4 w-4" /> Record eligibility check
            </Button>
            <Button
              size="sm"
              variant="outline"
              onClick={() => {
                const result = AdelanteEHR.requestReactivation(patientId, actor);
                toast.success(
                  result.staffTaskCreated
                    ? "Reactivation follow-up added to the case manager's worklist"
                    : "Client told we're following up — no case manager assigned, so no staff task was created",
                );
              }}
            >
              <RotateCw className="h-4 w-4" /> Start reactivation follow-up
            </Button>
            <Button
              size="sm"
              variant="outline"
              onClick={() => {
                const result = AdelanteEHR.addEnrollmentAssistTask(patientId, actor);
                toast.success(
                  result.staffTaskCreated
                    ? "Enrollment assistance added to the case manager's worklist"
                    : "Client told we'll help — no case manager assigned, so no staff task was created",
                );
              }}
            >
              <HelpingHand className="h-4 w-4" /> Start enrollment assistance
            </Button>
          </div>
          <p className="mt-3 text-xs text-muted-foreground">
            Nothing is sent to the county automatically. Follow-up actions create real staff work
            and tell the client what to expect.
          </p>
        </Card>
      )}

      <ul className="space-y-2">
        {rows.map((r) => {
          const last = log.find((e) => e.key === r.key);
          return (
            <li key={r.key} className="rounded border p-3 text-sm space-y-2">
              <div className="flex items-center justify-between">
                <span>
                  {r.label}
                  {last && (
                    <span className="block text-[11px] text-muted-foreground">
                      {last.value ? "Set on" : "Turned off"} by {last.actorId} ·{" "}
                      <ClientDate value={last.at} />
                    </span>
                  )}
                </span>
                <Switch checked={r.on} onCheckedChange={r.toggle} disabled={readOnly} />
              </div>
              {!readOnly && (
                <NoteInline
                  value={notes[r.key]?.note ?? ""}
                  asOf={notes[r.key]?.asOf}
                  onSave={(note, asOf) =>
                    AdelanteEHR.setEligibilityNote(patientId, r.key, note, asOf)
                  }
                />
              )}
            </li>
          );
        })}
      </ul>
      {checkOpen && (
        <CoverageCheckDialog
          patientId={patientId}
          open
          onOpenChange={(open) => !open && setCheckOpen(false)}
          actor={actor}
        />
      )}
    </div>
  );
}


export function NoteInline({
  value,
  asOf,
  onSave,
}: {
  value: string;
  asOf?: string;
  onSave: (note: string, asOf?: string) => void;
}) {
  const [note, setNote] = useState(value);
  const [when, setWhen] = useState(asOf ?? "");
  return (
    <div className="grid grid-cols-3 gap-2 items-end">
      <div className="col-span-2">
        <Label className="text-[10px] text-muted-foreground">Note / source</Label>
        <Input value={note} onChange={(e) => setNote(e.target.value)} className="h-8 text-xs" />
      </div>
      <div>
        <Label className="text-[10px] text-muted-foreground">As of</Label>
        <Input
          type="date"
          value={when}
          onChange={(e) => setWhen(e.target.value)}
          className="h-8 text-xs"
        />
      </div>
      <Button
        size="sm"
        variant="ghost"
        className="col-span-3 h-7 text-xs justify-end"
        onClick={() => {
          onSave(note, when || undefined);
          toast.success("Saved");
        }}
      >
        Save note
      </Button>
    </div>
  );
}

export function CoordinationTab({
