      {children}
    </div>
  );
}

export function CheckInsTab({ patientId, readOnly }: { patientId: string; readOnly?: boolean }) {
  const p = useEhr(() => AdelanteEHR.getPatient(patientId));
  const [modality, setModality] = useState<"phone" | "video" | "in_person" | "sms">("phone");
  const [attended, setAttended] = useState(true);
  const [notes, setNotes] = useState("");
  const [date, setDate] = useState(() => {
    const d = new Date();
    const pad = (n: number) => String(n).padStart(2, "0");
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
  });
  const [time, setTime] = useState(() => {
    const d = new Date();
    const pad = (n: number) => String(n).padStart(2, "0");
    return `${pad(d.getHours())}:${pad(d.getMinutes())}`;
  });
  const [dateError, setDateError] = useState<string | undefined>();
  const [timeError, setTimeError] = useState<string | undefined>();
  const items = p?.checkIns ?? [];
  const { role: viewerRole } = useActingStaff();
  const sharedRecovery = p ? staffVisibleRecoveryNotes(p, viewerRole) : [];
  return (
    <div className="space-y-3">
      {sharedRecovery.length > 0 && (
        <Card className="p-3 space-y-1" data-testid="shared-recovery-notes">
          <div className="text-xs uppercase tracking-wider text-muted-foreground">Shared by patient · protected</div>
          {sharedRecovery.map((r) => (
            <p key={r.id} className="text-sm">{r.text}</p>
          ))}
        </Card>
      )}
      {!readOnly && (
        <Card className="p-3 space-y-2">
          <div className="text-xs uppercase tracking-wider text-muted-foreground">
            Log new check-in
          </div>
          <div className="grid grid-cols-2 gap-2">
            <div className="space-y-1">
              <Label className="text-xs">Date</Label>
              <Input
                type="date"
                value={date}
                onChange={(e) => {
                  setDate(e.target.value);
                  setDateError(undefined);
                }}
                aria-invalid={Boolean(dateError)}
                className={dateError ? "border-2 border-input" : undefined}
              />
              {dateError && <p className="text-xs text-attention"><CircleAlert className="mr-1 inline size-4 shrink-0 align-text-bottom" aria-hidden="true" />{dateError}</p>}
            </div>
            <div className="space-y-1">
              <Label className="text-xs">Time</Label>
              <TimePicker
                id="drawer-checkin-time"
                value={time}
                onChange={(v) => {
                  setTime(v);
                  setTimeError(undefined);
                }}
                error={timeError}
                ariaLabel="Check-in time"
              />
            </div>
          </div>
          <div className="grid grid-cols-2 gap-2">
            <Select value={modality} onValueChange={(v) => setModality(v as typeof modality)}>
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="phone">Phone</SelectItem>
                <SelectItem value="video">Video</SelectItem>
                <SelectItem value="in_person">In-person</SelectItem>
                <SelectItem value="sms">SMS</SelectItem>
              </SelectContent>
            </Select>
            <label className="flex items-center gap-2 text-sm">
              <Checkbox checked={attended} onCheckedChange={(v) => setAttended(Boolean(v))} />
              Attended
            </label>
          </div>
          <Textarea
            rows={2}
            placeholder="Non-clinical note (e.g. confirmed housing intake Friday)."
            value={notes}
            onChange={(e) => setNotes(e.target.value)}
          />
          <Button
            size="sm"
            onClick={() => {
              setDateError(undefined);
              setTimeError(undefined);
              if (!date) {
                setDateError("Pick a date");
                return;
              }
              if (!time) {
                setTimeError("Pick a time");
                return;
              }
              const dt = new Date(`${date}T${time}`);
              if (isNaN(dt.getTime())) {
                setTimeError("That time isn't valid");
                return;
              }
              AdelanteEHR.addCheckIn(patientId, {
                date: dt.toISOString(),
                modality,
                attended,
                notes,
                needsFlagged: {},
              });
              setNotes("");
              toast.success("Check-in logged");
            }}
          >
            Log check-in
          </Button>
        </Card>
      )}
      <ul className="space-y-1">
        {items.length === 0 && <li className="text-xs text-muted-foreground">No check-ins yet.</li>}
        {items.map((c) => (
          <li key={c.id} className="rounded border p-2 text-sm">
            <div className="flex items-center justify-between">
              <span className="capitalize">{c.modality.replace("_", " ")}</span>
              <span className="text-xs text-muted-foreground">
                <ClientDate value={c.date} />
              </span>
            </div>
            {c.notes && <div className="text-xs text-muted-foreground mt-1">{c.notes}</div>}
          </li>
        ))}
      </ul>
    </div>
  );
}

export function ProviderHistoryTab({ patientId }: { patientId: string }) {
  const switches = useEhr(() => AdelanteEHR.listProviderSwitches({ patientId, status: "any" }));
  const clinicians = AdelanteEHR.listClinicians();
  const patient = useEhr(() => AdelanteEHR.getPatient(patientId));
  const { role, staffName, clinicianId } = useActingStaff();
  const [noteFor, setNoteFor] = useState<string | null>(null);
  const [note, setNote] = useState("");
  const canWrite = patient
    ? canAccess(role, "care_coordination", patient).level === "write"
    : false;
  const nameFor = (id: string) => clinicians.find((c) => c.id === id)?.name ?? id;
  const reasonLabel: Record<string, string> = {
    reschedule: "Reschedule",
    new_appointment: "New booking",
    refill_review: "Refill review",
    primary_reassignment: "Primary reassignment",
  };
  if (switches.length === 0) {
    return (
      <div className="text-sm text-muted-foreground">
        No provider switches recorded for this client.
      </div>
    );
  }
  return (
    <ul className="space-y-2">
      {switches.map((s) => {
        // Per-record authorization: only the outgoing provider this alert is
        // addressed to may resolve it — role-level write is necessary but
        // not sufficient.
        const isAddressee = Boolean(clinicianId && clinicianId === s.fromClinicianId);
        const actionable = s.status === "pending_review";
        return (
          <li key={s.id} className="rounded border p-3 text-sm">
            <div className="flex items-center justify-between gap-2">
              <div className="font-medium text-navy">
                {nameFor(s.fromClinicianId)} to {nameFor(s.toClinicianId)}
              </div>
              <StatusChip lang="en" state={s.status === "acknowledged" ? "done" : s.status === "pending_review" ? (isAddressee ? "yourturn" : "team") : "closed"} label={s.status.replace("_", " ")} />
            </div>
            <div className="mt-1 text-xs text-muted-foreground">
              {reasonLabel[s.reason] ?? s.reason}
              {s.serviceType ? ` · ${s.serviceType}` : ""}
              {" · "}
              {new Date(s.createdAt).toLocaleString()}
            </div>
            {s.context ? <div className="mt-1 text-xs">{s.context}</div> : null}
            {s.resolutionNote ? (
              <div className="mt-1 text-xs text-muted-foreground italic">
                Note: {s.resolutionNote}
              </div>
            ) : null}
            {s.resolvedBy ? (
              <div className="mt-1 text-[10px] text-muted-foreground">
                Resolved by {nameFor(s.resolvedBy)}
              </div>
            ) : null}
            {actionable &&
              (canWrite && isAddressee ? (
                <div className="mt-2 space-y-2">
                  {noteFor === s.id && (
                    <Textarea
                      rows={2}
                      className="text-xs"
                      placeholder="Hand-off / coordination note (optional)"
                      value={note}
                      onChange={(e) => setNote(e.target.value)}
                    />
                  )}
                  <div className="flex flex-wrap gap-2">
                    <Button
                      size="sm"
                      variant="outline"
                      className="h-7 text-[11px]"
                      onClick={() => {
                        AdelanteEHR.acknowledgeProviderSwitch(
                          s.id,
                          s.fromClinicianId,
                          note.trim() || undefined,
                        );
                        setNote("");
                        setNoteFor(null);
                        toast.success(`Switch acknowledged by ${staffName}`);
                      }}
                    >
                      Acknowledge
                    </Button>
                    <Button
                      size="sm"
                      variant="ghost"
                      className="h-7 text-[11px]"
                      onClick={() => {
                        AdelanteEHR.dismissProviderSwitch(
                          s.id,
                          s.fromClinicianId,
                          note.trim() || undefined,
                        );
                        setNote("");
                        setNoteFor(null);
                        toast("Alert dismissed");
                      }}
                    >
                      Don't use this draft
                    </Button>
                    {noteFor !== s.id && (
                      <Button
                        size="sm"
                        variant="ghost"
                        className="h-7 text-[11px]"
                        onClick={() => setNoteFor(s.id)}
                      >
                        Add note
                      </Button>
                    )}
                  </div>
                </div>
              ) : (
                <div className="mt-2 inline-flex items-center gap-1 text-[11px] text-muted-foreground">
                  <Lock className="h-3 w-3" />
                  {canWrite
                    ? `Only ${nameFor(s.fromClinicianId)} can resolve this hand-off.`
                    : "Your role cannot resolve provider switches."}
                </div>
              ))}
          </li>
        );
      })}
    </ul>
  );
}

/**
 * §Crisis Redesign Phase 2 — the SDOH-urgent trigger.
 *
 * Deliberately a manual, reasoned action. Nothing about the need text or its
 * status decides urgency: whether "no place to sleep tonight" is a crisis is a
 * human judgement, so a staff member states why and owns it.
 */
function FlagSdohUrgentControl({
  patientId,
  item,
  escalationOpen,
}: {
  patientId: string;
  item: { id: string; urgentEscalationId?: string; urgentFlaggedAt?: string };
  /**
   * True only while the LINKED escalation is still open. A resolved escalation
   * must not permanently disable re-escalation — the store already allows it
   * (`flagSdohItemUrgent` throws only on an open escalation), so the UI reads
   * the live escalation status rather than the historical flag timestamp.
   */
  escalationOpen: boolean;
}) {
  const { staffName } = useActingStaff();
  const [open, setOpen] = useState(false);
  const [reason, setReason] = useState("");
  if (escalationOpen) return null;
  if (!open)
    return (
      <Button size="sm" variant="outline" onClick={() => setOpen(true)}>
        <ShieldAlert className="mr-1 h-3.5 w-3.5" /> Flag as urgent
      </Button>
    );
  return (
    <div className="space-y-2 rounded border border-destructive/40 bg-destructive/5 p-2">
      <p className="text-[11px] text-muted-foreground">
        This puts the need in the urgent social needs lane of the crisis queue, routed to case
        management. Say why it cannot wait.
      </p>
      <Textarea
        rows={2}
        value={reason}
        onChange={(e) => setReason(e.target.value)}
        aria-label="Why this social need is urgent"
        placeholder="e.g. Loses shelter bed tonight; no other placement."
      />
      <div className="flex gap-2">
        <Button
          size="sm"
          variant="destructive"
          disabled={reason.trim().length < 3}
          onClick={() => {
            try {
              AdelanteEHR.flagSdohItemUrgent(patientId, item.id, staffName, reason);
              toast.success("Flagged urgent — it is now in the urgent social needs lane.");
              setOpen(false);
              setReason("");
            } catch (e) {
              toast.error(e instanceof Error ? e.message : "Could not flag this need.");
            }
          }}
        >
          Flag urgent
        </Button>
        <Button size="sm" variant="ghost" onClick={() => setOpen(false)}>
          Cancel
        </Button>
      </div>
    </div>
  );
}

export function SdohTab({ patientId, readOnly }: { patientId: string; readOnly: boolean }) {
  const p = useEhr(() => AdelanteEHR.getPatient(patientId));
  const { staffName, role } = useActingStaff();
  const items = p?.sdohPlan?.items ?? [];

  // The flag timestamp is history; the crisis-queue state is the escalation's
  // own status. Read the live row so a resolved need can be re-escalated.
  const urgentOpen = (escalationId: string | undefined) =>
    Boolean(
      escalationId && p?.crisisEscalations?.find((r) => r.id === escalationId)?.status === "open",
    );
  const [need, setNeed] = useState("");
  const [note, setNote] = useState("");
  const [visible, setVisible] = useState(true);
  // §5d-2 — one need at a time gets the Refer dialog; one at a time can be
  // confirmed for patient visibility when it is safety-sensitive.
  const [referItem, setReferItem] = useState<SdohPlanItem | null>(null);
  const [safetyReveal, setSafetyReveal] = useState<SdohPlanItem | null>(null);
  const unmaterialized = useEhr(() =>
    JSON.stringify(AdelanteEHR.unmaterializedHrsnDomains(patientId)),
  );
  const pendingDomains = JSON.parse(unmaterialized) as { key: string; label: string }[];
  const statusOpts: SdohStatus[] = [
    "identified",
    "sent",
    "accepted",
    "scheduled",
    "completed",
    "not_completed",
  ];
  return (
    <div className="space-y-3">
      {!readOnly && pendingDomains.length > 0 && (
        <Card className="p-3 space-y-2 border-teal/40">
          <div className="text-xs uppercase tracking-wider text-muted-foreground">
            From the social-needs screening
          </div>
          <p className="text-sm text-navy">
            {pendingDomains.length} positive screening result
            {pendingDomains.length === 1 ? " has" : "s have"} no trackable need yet:{" "}
            {pendingDomains.map((d) => d.label).join(", ")}.
          </p>
          <p className="text-[11px] text-muted-foreground">
            Interpersonal safety is created staff-only — it is never shown to the patient or an
            advocate unless you choose to share it.
          </p>
          <Button
            size="sm"
            onClick={() => {
              const res = AdelanteEHR.materializeHrsnNeeds(patientId, { staffName, role });
              toast.success(`${res.created} need${res.created === 1 ? "" : "s"} created.`);
            }}
          >
            <Plus className="h-4 w-4 mr-1" /> Create trackable needs from screening
          </Button>
        </Card>
      )}
      {!readOnly && (
        <Card className="p-3 space-y-2">
          <div className="text-xs uppercase tracking-wider text-muted-foreground">
            Add SDOH item
          </div>
          <Input
            placeholder="Need (e.g. transportation to appointment)"
            value={need}
            onChange={(e) => setNeed(e.target.value)}
          />
          <Textarea
            rows={2}
            placeholder="Action item / note"
            value={note}
            onChange={(e) => setNote(e.target.value)}
          />
          <label className="flex items-center gap-2 text-xs">
            <Switch checked={visible} onCheckedChange={setVisible} />
            Show on patient portal
          </label>
          <Button
            size="sm"
            onClick={() => {
              AdelanteEHR.addSdohItem(
                patientId,
                { need, note, visibleToPatient: visible },
                { staffName, role },
              );

              setNeed("");
              setNote("");
              toast.success("SDOH item added");
            }}
          >
            <Plus className="h-4 w-4 mr-1" /> Add
          </Button>
        </Card>
      )}
      <ul className="space-y-2">
        {items.length === 0 && (
          <li className="text-xs text-muted-foreground">No SDOH items logged.</li>
        )}
        {items.map((i) => (
          <li key={i.id} className="rounded border p-3 space-y-2 text-sm">
            <div className="flex items-start justify-between gap-2">
              <div className="font-medium text-navy">
                {i.need}
                {i.visibleToPatient === false && (
                  <Badge variant="outline" className="ml-2 text-[10px]">
                    Staff only
                  </Badge>
                )}
              </div>
              <StatusChip lang="en" state={i.status === "completed" ? "done" : i.status === "identified" || i.status === "not_completed" ? (i.createdBy === staffName || i.createdByRole === role ? "yourturn" : "team") : "team"} label={i.status.replace("_", " ")} />
            </div>
            <div className="flex flex-wrap gap-1.5 text-[10px]" data-testid="staff-need-meta">
              <Badge variant="outline" className="text-[10px]">
                Category: {categoryName(i.categoryId ?? matchResourcesForNeed(i)?.categoryIds[0]) ?? "—"}
              </Badge>
              <Badge variant="outline" className="text-[10px]">{(_SRC ?? {})[i.source]}</Badge>
              {i.urgency && (
                <Badge variant={i.urgency === "today" ? "outline" : "outline"} className="text-[10px]">
                  Urgency: {URGENCY_LABEL.en[i.urgency]}
                </Badge>
              )}
            </div>
            <NeedReferralList patientId={patientId} itemId={i.id} />
            <NeedAgingLine patientId={patientId} item={i} />
            <SdohActivityLog
              patientId={patientId}
              target="need"
              targetId={i.id}
              {...(i.log ? { log: i.log } : {})}
              {...(i.note ? { legacyNote: i.note } : {})}
              readOnly={readOnly}
            />
            <AttributionLine
              {...(i.createdBy ? { createdBy: i.createdBy, createdAt: i.createdAt } : {})}
              {...(i.lastUpdatedBy
                ? {
                    updatedBy: i.lastUpdatedBy,
                    ...(i.updatedAt ? { updatedAt: i.updatedAt } : {}),
                  }
                : {})}
            />

            {i.urgentFlaggedAt &&
              (urgentOpen(i.urgentEscalationId) ? (
                <div className="text-[11px] text-destructive">
                  Flagged urgent by {i.urgentFlaggedBy} · <ClientDate value={i.urgentFlaggedAt} /> —
                  open in the urgent social needs lane of the crisis queue.
                </div>
              ) : (
                <div className="text-[11px] text-muted-foreground">
                  Previously flagged urgent by {i.urgentFlaggedBy} ·{" "}
                  <ClientDate value={i.urgentFlaggedAt} /> — that escalation is resolved. Flag again
                  if it is urgent now.
                </div>
              ))}
            {!readOnly && (
              <FlagSdohUrgentControl
                patientId={patientId}
                item={i}
                escalationOpen={urgentOpen(i.urgentEscalationId)}
              />
            )}
            {!readOnly && (
              <div className="flex flex-wrap items-center gap-2">
                <Button size="sm" variant="outline" onClick={() => setReferItem(i)}>
                  <Building2 className="h-3.5 w-3.5 mr-1" /> Refer
                </Button>
                <Select
                  value={i.status}
                  onValueChange={(v) =>
                    AdelanteEHR.setSdohStatus(patientId, i.id, v as SdohStatus, undefined, {
                      staffName,
                      role,
                    })
                  }


                >
                  <SelectTrigger className="h-8 text-xs w-[160px]">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {statusOpts.map((s) => (
                      <SelectItem key={s} value={s} className="capitalize">
                        {s.replace("_", " ")}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <Button
                  size="sm"
                  variant="ghost"
                  onClick={() => {
                    // §5d-2 — turning a safety need ON for the patient is a
                    // risk decision, so it asks first. Turning it off never does.
                    if (i.safetySensitive && i.visibleToPatient === false) {
                      setSafetyReveal(i);
                      return;
                    }
                    AdelanteEHR.setSdohVisibility(patientId, i.id, !i.visibleToPatient);
                  }}
                >
                  {i.visibleToPatient ? (
                    <>
                      <Eye className="h-3.5 w-3.5 mr-1" /> Visible
                    </>
                  ) : (
                    <>
                      <EyeOff className="h-3.5 w-3.5 mr-1" /> Hidden
                    </>
                  )}
                </Button>
                <Button
                  size="sm"
                  variant="ghost"
                  onClick={() => AdelanteEHR.removeSdohItem(patientId, i.id)}
                >
                  <Trash2 className="h-3.5 w-3.5" />
                </Button>
              </div>
            )}
          </li>
        ))}
      </ul>
      {referItem && (
        <ReferForNeedDialog
          patientId={patientId}
          item={referItem}
          open
          onOpenChange={(v) => !v && setReferItem(null)}
        />
      )}
      <AlertDialog open={Boolean(safetyReveal)} onOpenChange={(v) => !v && setSafetyReveal(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Show this safety need to the patient?</AlertDialogTitle>
            <AlertDialogDescription>
              Someone who has disclosed interpersonal safety risk may be living with the person
              harming them. Making this visible puts it on their portal and their phone, and shares
              it with an authorized advocate. Only do this if you have talked it through with them.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep staff only</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => {
                if (safetyReveal) AdelanteEHR.setSdohVisibility(patientId, safetyReveal.id, true);
                setSafetyReveal(null);
              }}
            >
              Make visible
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

/**
 * §5d-2 — the referrals made for one need, read through the single lookup.
 * Directory link state is shown honestly: an org that has been unpublished
 * still names the referral, flagged as no longer listed.
 */
/**
 * §5d-3 — draft aging read. Nothing is stamped: this is elapsed time since the
 * last real action, including an activity-log entry.
 */
function NeedAgingLine({ patientId, item }: { patientId: string; item: SdohPlanItem }) {
  const count = useEhr(() => AdelanteEHR.referralsForNeed(patientId, item.id).length);
  const aging = sdohNeedAging(item, count);
  if (aging.state !== "due" && aging.state !== "overdue") return null;
  return (
    <div
      className={`text-[11px] ${aging.state === "overdue" ? "text-attention" : "text-muted-foreground"}`}
    >
      {sdohAgingLabel(aging)} · {SDOH_AGING_DRAFT.label}
    </div>
  );
}

function NeedReferralList({ patientId, itemId }: { patientId: string; itemId: string }) {
  const json = useEhr(() => JSON.stringify(AdelanteEHR.referralsForNeed(patientId, itemId)));
  const refs = JSON.parse(json) as ResourceReferral[];
  if (refs.length === 0) return null;
  return (
    <ul className="space-y-1">
      {refs.map((r) => {
        const link = resourceLinkState(r);
        return (
          <li key={r.id} className="text-xs text-muted-foreground flex flex-wrap items-center gap-1.5">
            <Building2 className="h-3 w-3" />
            <span className="text-navy">{referralProviderLabel(r)}</span>
            <Badge variant="outline" className="text-[10px]">
              {RESOURCE_REFERRAL_OUTCOME_LABEL[r.status]}
            </Badge>
            {link.kind === "external" && <span>Not in the directory</span>}
            {link.kind === "inactive" && <span>Directory listing not published</span>}
            {link.kind === "missing" && <span>No longer in the directory</span>}
            {!isReferralOpen(r) && <span>· closed</span>}
          </li>
        );
      })}
    </ul>
  );
}

/**
 * §5d-1 — attribution line shown inline on needs and referrals.
 */
function AttributionLine({
  createdBy,
  createdAt,
  updatedBy,
  updatedAt,
}: {
  createdBy?: string;
  createdAt?: string;
  updatedBy?: string;
  updatedAt?: string;
}) {
  if (!createdBy && !updatedBy) return null;
  return (
    <div className="text-[11px] text-muted-foreground">
      {createdBy && (
        <span>
          Added by {createdBy}
          {createdAt && (
            <>
              {" · "}
              <ClientDate value={createdAt} />
            </>
          )}
        </span>
      )}
      {createdBy && updatedBy && " — "}
      {updatedBy && (
        <span>
          Updated by {updatedBy}
          {updatedAt && (
            <>
              {" · "}
              <ClientDate value={updatedAt} />
            </>
          )}
        </span>
      )}
    </div>
  );
}

export function ReferralsTab({
  patientId,
  sudGated,
