}) {
  if (items.length === 0) return null;
  const originLabels: Record<CaseTask["origin"], string> = {
    manual: "Manual",
    missed_appt: "Missed visit",
    screener_flag: "Screener",
    asam_needed: "ASAM",
    referral_stale: "Stale referral",
    referral_enrollment_setup: "New enrollment setup",
    advocate_ahcd_validation: "AHCD validation",
    notification_failed: "Delivery failed",
    provider_switch: "Provider switch",
    note_automation: "Note automation",
    med_side_effect: "Side effect reported",
    sdoh_follow_up: "Social-needs follow-up",
    recovery_journey_review: "Screener",
  };
  return (
    <div className="space-y-1.5">
      <div className="text-[10px] uppercase tracking-wider text-muted-foreground">{label}</div>
