                        aria-label="Snooze 3 days"
                      >
                        Snooze
                      </Button>
                      <Button
                        size="sm"
                        variant="outline"
                        className="h-7 text-[11px]"
                        onClick={() => AdelanteEHR.completeCaseTask(t.id)}
                      >
                        Done
                      </Button>
                    </>
                  )}
                  {t.status === "snoozed" && (
                    <Button
                      size="sm"
                      variant="ghost"
                      className="h-7 text-[11px]"
                      onClick={() => AdelanteEHR.reopenCaseTask(t.id)}
                    >
                      Reopen
                    </Button>
                  )}
                </div>
              )}
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
}

// ---------- Care Plan tab (consolidated from clinician.tsx) ----------
// §Part B1 — goals SUGGESTED from the patient's "looking for" answers. Nothing
// reaches the care plan until a clinician accepts; accept/dismiss is audited.
function SuggestedGoalsPanel({ patientId, readOnly }: { patientId: string; readOnly?: boolean }) {
  const { staffName, role } = useActingStaff();
  const json = useEhr(() =>
    JSON.stringify(
      (AdelanteEHR.getPatient(patientId)?.suggestedGoals ?? []).filter(
        // §Part 2 — ASAM-derived goal suggestions are SUD content.
        (g) => g.status === "suggested" && (g.reason !== "asam_signed" || roleSeesAsamSectionForGoals(role, AdelanteEHR.getPatient(patientId))),
      ),
    ),
  );
  const items = JSON.parse(json) as { id: string; text: string; reason: string }[];
  if (items.length === 0) return null;
  return (
    <Card className="p-4 border-dashed" data-testid="suggested-goals">
      <h4 className="font-display text-sm text-navy">Suggested goals</h4>
      <p className="text-[11px] text-muted-foreground mt-0.5">
        From what the patient said they're looking for at intake. Not on the care plan until you accept.
      </p>
      <ul className="mt-2 space-y-2">
        {items.map((g) => (
          <li key={g.id} className="flex flex-wrap items-center gap-2 rounded-md border p-2 text-sm">
            <span className="flex-1">{g.text}</span>
            {!readOnly && (
              <>
                <Button size="sm" data-testid={`suggested-accept-${g.id}`} onClick={() => AdelanteEHR.acceptSuggestedGoal(patientId, g.id, { name: staffName, role })}>
                  Accept
                </Button>
                <Button size="sm" variant="outline" onClick={() => AdelanteEHR.dismissSuggestedGoal(patientId, g.id, { name: staffName, role })}>
                  Don't use this draft
                </Button>
              </>
            )}
          </li>
        ))}
      </ul>
    </Card>
  );
}

export function CarePlanTab({ patientId, readOnly }: { patientId: string; readOnly?: boolean }) {
  const confirmation = useConfirmDialog();
  const patient = useEhr(() => AdelanteEHR.getPatient(patientId));
  const { staffName } = useActingStaff();
  const [planDraft, setPlanDraft] = useState(patient?.carePlanOverride?.text ?? "");
  const [dirty, setDirty] = useState(false);
  const [newGoal, setNewGoal] = useState("");
  useEffect(() => {
    setPlanDraft(patient?.carePlanOverride?.text ?? "");
    setDirty(false);
  }, [patient?.carePlanOverride?.text]);
  useDraftDirty(`care-plan:${patientId}`, dirty || newGoal.trim().length > 0);
  if (!patient) return null;
  const existing = patient.carePlanOverride?.text ?? "";
  const trimmed = planDraft.trim();
  const isClearing = dirty && trimmed.length === 0 && existing.length > 0;
  const unchanged = !dirty && trimmed === existing.trim();
  return (
    <div className="space-y-4">
      {confirmation.dialog}
      <CarePlanCard patientId={patient.id} audience="clinician" />
      <CarePlanEditor patientId={patient.id} readOnly={readOnly} />
      <SuggestedGoalsPanel patientId={patient.id} readOnly={readOnly} />
      {/* §5-stage journey — care-team view of the person-set stage. Same
          component the patient sees, so the model can't drift between them. */}
      <Card className="p-4">
        <h4 className="font-display text-sm text-navy">Recovery journey stage</h4>
        <p className="mb-3 mt-0.5 text-[11px] text-muted-foreground">
          Person-set, never computed. The patient can set this themselves; a care-team change is
          audited the same way.
        </p>
        <RecoveryStagePanel
          patientId={patient.id}
          actor="staff"
          actorName={staffName}
          {...(readOnly ? { readOnly: true } : {})}
        />
      </Card>
      <Card className="p-4">
        <h4 className="font-display text-sm text-navy">Care plan note</h4>
        <p className="text-[11px] text-muted-foreground mt-0.5">
          Optional clinician note appended to the auto-summary shown to the patient.
        </p>
        <Textarea
          className="mt-2 min-h-[100px]"
          value={planDraft}
          disabled={readOnly}
          placeholder="Optional note…"
          onChange={(e) => {
            setPlanDraft(e.target.value);
            setDirty(true);
          }}
        />
        {!readOnly && (
          <Button
            className="mt-3 bg-navy text-navy-foreground hover:bg-navy/90"
            disabled={unchanged}
            onClick={() => {
              if (isClearing) {
                confirmation.ask({ title: "Clear this care-plan note?", description: "The optional summary note is removed. Goals and signed notes stay unchanged. The text is not recoverable from this field; no notification is sent.", confirmLabel: "Clear note", keepLabel: "Keep note", requireReason: true, onConfirm: reason => { confirmedAction("plan_summary_clear", "updateCarePlanSummary", patient.id, reason, patient.id, "", staffName); setDirty(false); toast.success("Care plan note cleared"); return true; } });
                return;
              }
              AdelanteEHR.updateCarePlanSummary(patient.id, planDraft, staffName);
              setDirty(false);
              toast.success(isClearing ? "Care plan note cleared" : "Care plan updated");
            }}
          >
            Save note
          </Button>
        )}
      </Card>
      <Card className="p-4">
        <h4 className="font-display text-sm text-navy">Goals</h4>
        <div className="mt-2 space-y-2">
          {(patient.goals ?? []).length === 0 && (
            <p className="text-xs text-muted-foreground">No goals yet.</p>
          )}
          {(patient.goals ?? []).map((g) => (
            <div key={g.id} className="flex items-start gap-2 rounded-md border p-2 text-sm">
              <Select
                value={g.status}
                disabled={readOnly}
                onValueChange={(v) =>
                  AdelanteEHR.setGoalStatus(patient.id, g.id, v as never, staffName)
                }
              >
                <SelectTrigger className="h-7 w-[120px] text-xs">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="open">Open</SelectItem>
                  <SelectItem value="in_progress">In progress</SelectItem>
                  <SelectItem value="done">Done</SelectItem>
                </SelectContent>
              </Select>
              <span className="flex-1 pt-1">{g.text}</span>
              {g.createdBy && (
                <span className="pt-1 text-[10px] text-muted-foreground whitespace-nowrap">
                  {g.createdBy}
                </span>
              )}
              {!readOnly && (
                <Button
                  size="icon"
                  variant="ghost"
                  className="h-7 w-7"
                  onClick={() => AdelanteEHR.removeGoal(patient.id, g.id)}
                >
                  <Trash2 className="h-3.5 w-3.5" />
                </Button>
              )}
            </div>
          ))}
        </div>
        {!readOnly && (
          <div className="mt-3 flex gap-2">
            <Input
              placeholder="Add a goal…"
              value={newGoal}
              onChange={(e) => setNewGoal(e.target.value)}
            />
            <Button
              size="sm"
              onClick={() => {
                if (!newGoal.trim()) return;
                AdelanteEHR.addGoal(patient.id, newGoal, staffName);
                setNewGoal("");
              }}
            >
              <Plus className="h-4 w-4" />
            </Button>
          </div>
        )}
      </Card>
    </div>
  );
}

// ---------- Notes tab (progress SOAP notes + sign/cosign) ----------
// Attestation is checkbox-only, matching Orders / MAR / Refusal. Signer
// eligibility is role-based (see src/lib/notes.ts for the known simplification
// vs. credential-checked signing).
export function NotesTab({
  patientId,
  readOnly,
  initialTemplateKey,
  restrictToTemplateKey,
}: {
  patientId: string;
  readOnly?: boolean;
  /** Pre-selects a seeded template by key (e.g. the release → discharge flow). */
  initialTemplateKey?: string;
  /**
   * §Phase 3 — scopes the tab to ONE template's notes (CHW service notes).
   * A role that only holds `chw_notes` must not see the rest of the chart's
   * documentation, so the list is filtered here, not just the picker.
   */
  restrictToTemplateKey?: string;
}) {
  const patient = useEhr(() => AdelanteEHR.getPatient(patientId));
  const { staffName, staffId, clinicianId, role } = useActingStaff();
  const { t: tr } = useI18n();
  const [note, setNote] = useState({
    sessionType: "individual" as "individual" | "group" | "phone" | "check_in",
    subjective: "",
    objective: "",
    assessment: "",
    plan: "",
    category: "none" as "none" | "sud" | "mental_health" | "pregnancy" | "medical",
  });
  // Template layer: "none" keeps the existing free-text SOAP editor untouched.
  // §EHR audit Phase 2b — the picker was previously unfiltered, which was the
  // one real inconsistency with the permission-checked admin page. It is now
  // scoped by USE rights (System + own discipline + own personal templates),
  // which is deliberately broader than EDIT rights: picking a template is
  // documentation, authoring one is configuration.
  const allTemplates = useEhr(() => AdelanteEHR.listNoteTemplates());
  const templates = templatesVisibleTo(allTemplates, { role, staffId });
  const [templateId, setTemplateId] = useState<string>(
    () =>
      ((initialTemplateKey ?? restrictToTemplateKey)
        ? AdelanteEHR.listNoteTemplates().find(
            (t) => t.key === (initialTemplateKey ?? restrictToTemplateKey),
          )?.id
        : undefined) ?? "none",
  );
  const [answers, setAnswers] = useState<TemplateAnswers>({});
  const activeTemplate = templates.find((t) => t.id === templateId);
  // §Phase 3b — draft orders staged from this note's orders_section. They are
  // real draft MedOrders from the moment they are created; this only tracks
  // which ones came from the note so they can be stamped with its id.
  const [stagedOrderIds, setStagedOrderIds] = useState<string[]>([]);
  // §Phase 1e — which attended visit this note documents. `null` means "use
  // the unambiguous default"; a string is an explicit clinician choice.
  const [visitChoice, setVisitChoice] = useState<string | null>(null);
  const appointments = useEhr(() => AdelanteEHR.listAppointments());
  const composeAutofill = useNoteAutofillSnapshots(patientId, activeTemplate?.schema);
  useDraftDirty(
    `notes:${patientId}`,
    Boolean(
      note.subjective.trim() || note.objective.trim() || note.assessment.trim() || note.plan.trim(),
    ),
  );
  if (!patient) return null;
  // Acting staff always resolves to a named person; `clinicianId` is only
  // present for staff linked to a provider record. Notes are attributed to
  // the provider record when there is one, otherwise to the staff id.
  const authorId = clinicianId ?? staffId;
  const canWrite = !readOnly;
  const clinicians = AdelanteEHR.listClinicians();
  const visitLink = resolveVisitLink(appointments, patient.progressNotes ?? [], {
    patientId: patient.id,
    authorId,
    noteDate: new Date().toISOString(),
  });
  const selectedVisitId = visitChoice ?? visitLink.defaultId ?? NO_VISIT;
  const clinicianLabel = (id: string) =>
    clinicians.find((c) => c.id === id)?.name ?? getStaffMember(id)?.name ?? id;
  // Same 42 CFR Part 2 gate that hides SUD problem entries — one mechanism.
  const noteGate = (n: ProgressNote) => {
    // Draft — pending executive RBAC review: metadata-only roles see the header, not the body.
    if (noteBodyRestricted(role, patient, n, [staffId, clinicianId])) return { locked: true, reason: NOTE_CONTENT_RESTRICTED };
    const cls = noteGateClass(n);
    return cls ? canAccess(role, cls, patient) : { locked: false, reason: undefined };
  };
  const visibleNotes = (patient.progressNotes ?? []).filter(
    (n) => !restrictToTemplateKey || n.templateKey === restrictToTemplateKey,
  );
  return (
    <div className="space-y-4">
      {!restrictToTemplateKey && canCaptureScribe(role) && (
        <StartScribeLink patientId={patientId} />
      )}
      {canWrite && (
        <Card className="p-4">
          <h4 className="font-display text-sm text-navy" data-testid="note-composer-heading">
            {restrictToTemplateKey === "chw_service" ? tr("chwNoteHeading") : "New progress note"}
          </h4>
          <p className="mt-0.5 text-[11px] text-muted-foreground">
            Authoring as <span className="text-navy font-medium">{staffName}</span>
          </p>
          {!authorId && (
            <p className="mt-1 text-[11px] text-attention"><CircleAlert className="mr-1 inline size-4 shrink-0 align-text-bottom" aria-hidden="true" />
              No acting staff identity on this session — pick a staff member to author notes.
            </p>
          )}
          <div className="mt-3 space-y-3">
            <div className="space-y-1.5">
              <Label className="text-xs">Session type</Label>
            </div>
            <div className="space-y-1.5">
              <Label className="text-xs">Template</Label>
              <NoteTemplatePicker
                templates={
                  restrictToTemplateKey
                    ? templates.filter((t) => t.key === restrictToTemplateKey)
                    : templates
                }
                value={templateId}
                onChange={(v) => {
                  setTemplateId(v);
                  setAnswers({});
                }}
                canClone={(t) => canCloneTemplate({ role, staffId }, t)}
                onClone={(t) => {
                  try {
                    const copy = actFor<ReturnType<typeof AdelanteEHR.cloneNoteTemplateToPersonal>>("note_template_clone", "cloneNoteTemplateToPersonal", patientId, t.id, {
                      staffId,
                      staffName,
                    });
                    setTemplateId(copy.id);
                    setAnswers({});
                    toast.success("Saved as your own copy — the original is untouched.");
                  } catch (e) {
                    toast.error((e as Error).message);
                  }
                }}
              />
            </div>
            <div className="space-y-1.5">
              <Select
                value={note.sessionType}
                onValueChange={(v) => setNote({ ...note, sessionType: v as never })}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="individual">Individual</SelectItem>
                  <SelectItem value="group">Group</SelectItem>
                  <SelectItem value="phone">Phone</SelectItem>
                  <SelectItem value="check_in">Check-in</SelectItem>
                </SelectContent>
              </Select>
              <label className="flex items-center gap-2 text-xs" title="Draft — pending clinical sign-off. Crisis notes must be signed within 1 calendar day.">
                <input
                  type="checkbox"
                  aria-label="Crisis intervention"
                  checked={(note as { serviceType?: string }).serviceType === "crisis_intervention"}
                  onChange={(e) => setNote({ ...note, serviceType: e.target.checked ? "crisis_intervention" : undefined } as never)}
                />
                Crisis intervention (1-day signing clock)
              </label>
            </div>
            <div className="space-y-1.5">
              <Label className="text-xs">Sensitivity context</Label>
              <Select
                value={note.category}
                onValueChange={(v) => setNote({ ...note, category: v as never })}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="none">General</SelectItem>
                  <SelectItem value="mental_health">Mental health</SelectItem>
                  <SelectItem value="sud">SUD — 42 CFR Part 2</SelectItem>
                  <SelectItem value="pregnancy">Pregnancy</SelectItem>
                  <SelectItem value="medical">Medical</SelectItem>
                </SelectContent>
              </Select>
              <p className="text-[10px] text-muted-foreground">
                A SUD note is masked by the same consent gate as SUD problem entries.
              </p>
            </div>
            {activeTemplate && (
              <div className="rounded-md border border-border p-3">
                <TemplateForm
                  schema={activeTemplate.schema}
                  answers={answers}
                  onChange={setAnswers}
                  language={patient.preferredLanguage === "es" ? "es" : "en"}
                  renderSection={(section) =>
                    section.type === "orders_section" ? (
                      <NoteOrdersSection
                        patientId={patient.id}
                        section={section}
                        stagedIds={stagedOrderIds}
                        onStage={(id) => setStagedOrderIds((prev) => [...prev, id])}
                      />
                    ) : (
                      (() => {
                        const snap = composeAutofill.find((s) => s.sectionId === section.id);
                        return snap ? <NoteAutofillCard snapshot={snap} /> : null;
                      })()
                    )
                  }
                />
              </div>
            )}
            {(["subjective", "objective", "assessment", "plan"] as const).map((k) => (
              <div key={k} className="space-y-1.5">
                <Label className="text-xs capitalize">{k}</Label>
                <Textarea
                  value={note[k]}
                  rows={2}
                  onChange={(e) => setNote({ ...note, [k]: e.target.value })}
                />
              </div>
            ))}
            {/* §Phase 1e — the visit this note documents. Defaults only when
                exactly one attended, undocumented visit of this author's is on
                the same day; otherwise the clinician picks. */}
            <div className="space-y-1.5" data-testid="note-visit-link">
              <Label className="text-xs">Visit this note documents</Label>
              <Select
                value={selectedVisitId}
                onValueChange={(v) => setVisitChoice(v)}
              >
                <SelectTrigger data-testid="note-visit-link-select">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value={NO_VISIT}>No visit — not tied to an appointment</SelectItem>
                  {visitLink.candidates.map((c) => (
                    <SelectItem key={c.appointment.id} value={c.appointment.id}>
                      {new Date(c.appointment.start).toLocaleString()} ·{" "}
                      {clinicianLabel(c.appointment.clinicianId)}
                      {c.sameDayOwn ? " · today, your visit" : ""}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <p className="text-[10px] text-muted-foreground" data-testid="note-visit-link-hint">
                {visitLink.ambiguous && visitChoice === null
                  ? "More than one attended visit today — choose which one this note documents."
                  : selectedVisitId === NO_VISIT
                    ? visitLink.candidates.length === 0
                      ? "No attended visit is waiting for documentation, so this note is not linked to one."
                      : "Not linked to a visit. Link it if this note documents one."
                    : visitChoice === null
                      ? "Linked automatically to today's attended visit — change it if that's wrong."
                      : "Linked to the visit you chose."}
              </p>
            </div>
            <Button
              className="w-full bg-navy text-navy-foreground hover:bg-navy/90"
              disabled={!authorId || (visitLink.ambiguous && visitChoice === null)}
              onClick={() => {
                if (!authorId) return;
                if (visitLink.ambiguous && visitChoice === null) {
                  toast.error("Choose which visit this note documents");
                  return;
                }
                if (!note.subjective.trim()) {
                  toast.error("Add at least a subjective entry");
                  return;
                }
                const saved = act<ReturnType<typeof AdelanteEHR.addProgressNote>>("progress_note", "addProgressNote", patient.id, {
                  clinicianId: authorId,
                  ...(selectedVisitId !== NO_VISIT ? { appointmentId: selectedVisitId } : {}),
                  date: new Date().toISOString(),
                  sessionType: note.sessionType,
                  ...((note as { serviceType?: string }).serviceType === "crisis_intervention" ? { serviceType: "crisis_intervention" as const } : {}),
                  subjective: note.subjective,
                  objective: note.objective,
                  assessment: note.assessment,
                  plan: note.plan,
                  category: note.category === "none" ? undefined : note.category,
                  authorSource: "human",
                  status: "draft",
                  templateId: activeTemplate?.id,
                  templateKey: activeTemplate?.key,
                  templateTitle: activeTemplate?.title,
                  templateVersion: activeTemplate?.version,
                  // Snapshot the schema so a later template edit never rewrites
                  // the questions a clinician actually answered.
                  templateSchema: activeTemplate?.schema,
                  templateAnswers: activeTemplate ? answers : undefined,
                });
                // Traceability only — the orders keep their own lifecycle.
                if (saved) AdelanteEHR.linkOrdersToNote(patient.id, saved.id, stagedOrderIds);
                toast.success("Progress note saved as draft");
                setStagedOrderIds([]);
                setVisitChoice(null);
                setAnswers({});
                setNote({
                  sessionType: "individual",
                  subjective: "",
                  objective: "",
                  assessment: "",
                  plan: "",
                  category: "none",
                });
              }}
            >
              Save draft
            </Button>
          </div>
        </Card>
      )}
      <div className="space-y-2">
        <h4 className="font-display text-sm text-navy">Recent notes</h4>
        {visibleNotes.length === 0 && (
          <Card className="p-3 text-xs text-muted-foreground">No progress notes yet.</Card>
        )}
        {visibleNotes.map((n) => (
          <ProgressNoteCard
            key={n.id}
            patientId={patient.id}
            note={n}
            canWrite={canWrite}
            // §Group sessions — one gate helper decides which record class
            // masks a note (SUD, group, or psychotherapy tier).
            sudLocked={noteGate(n).locked}
            sudReason={noteGate(n).reason}
            authorLabel={
              clinicians.find((c) => c.id === n.clinicianId)?.name ??
              getStaffMember(n.clinicianId)?.name ??
              n.clinicianId
            }
          />
        ))}
      </div>
    </div>
  );
}

const NOTE_STATUS_LABEL: Record<NoteStatus, string> = {
  draft: "Draft",
  signed: "Signed",
  cosign_pending: "Awaiting cosign",
  cosigned: "Cosigned",
  declined: "Declined",
};

/**
 * Export action for finalized notes. Rendered ONLY when `noteExportGate`
 * allows it — the same gate the PDF builder re-runs — so draft, unsigned and
 * SUD-masked notes have no export affordance at all.
 */
function NoteExportButton({
  patientId,
  note,
  authorLabel,
}: {
  patientId: string;
  note: ProgressNote;
  authorLabel: string;
}) {
  const patient = useEhr(() => AdelanteEHR.getPatient(patientId));
  const { role, staffName, staffId } = useActingStaff();
  if (!patient) return null;
  if (!noteExportGate(note, role, patient).allowed) return null;
  return (
    <Button
      size="sm"
      variant="outline"
      className="mt-2 h-7 text-[11px]"
      onClick={() => {
        try {
          const filename = downloadProgressNotePdf({
            note,
            patient,
            role,
            authorLabel,
            exportedBy: staffName,
          });
          recordView({ actorId: staffId, actorName: staffName, role, patientId: patient.id, sectionId: `note-pdf:${note.id}`, kind: "export" });
          toast.success(`Exported ${filename}`);
        } catch (e) {
          toast.error((e as Error).message);
        }
      }}
    >
      <Download className="mr-1 h-3.5 w-3.5" /> Export PDF
    </Button>
  );
}

export function NoteStatusBadge({ note }: { note: ProgressNote }) {
  const s = noteStatus(note);
  const actor = useActingStaff();
  const author = [note.signedById, note.clinicianId].some((id) => Boolean(id) && (id === actor.staffId || id === actor.clinicianId)) || note.signedBy === actor.staffName;
  const mine = s === "cosign_pending" ? isMyCosign(note, actor) : author;
  return <StatusChip lang="en" state={s === "cosigned" || s === "signed" ? "done" : mine ? "yourturn" : "team"} label={NOTE_STATUS_LABEL[s]} />;
}

// §EHR audit Phase 1d — the wording now lives in the versioned statement
// catalog (`ATTESTATION_STATEMENTS`), so the exact text shown is frozen onto
// the signed record. This constant is kept only as the legacy alias.
const SIGN_ATTESTATION = ATTESTATION_STATEMENTS["progress_note_sign"]!.text;


/** Read-only trace of the orders that originated from a finalized note. */
function NoteOrderTrace({ orders, title }: { orders: MedOrder[]; title: string }) {
  return (
    <div className="rounded-md border border-border bg-secondary/20 p-3">
      <h5 className="font-display text-sm text-navy">{title}</h5>
      {orders.length === 0 ? (
        <p className="mt-1 text-[11px] text-muted-foreground">No orders placed from this note.</p>
      ) : (
        <ul className="mt-1 space-y-1">
          {orders.map((o) => (
            <li key={o.id} className="text-[11px] text-navy">
              {o.drugName}
              <span className="text-muted-foreground"> · {o.status}</span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

function ProgressNoteCard({
  patientId,
  note,
  canWrite,
  sudLocked,
  sudReason,
  authorLabel,
}: {
  patientId: string;
  note: ProgressNote;
  canWrite: boolean;
  sudLocked: boolean;
  sudReason?: string;
  authorLabel: string;
}) {
  const { staffName, role, staffId: actingStaffId, clinicianId: actingClinicianId } =
    useActingStaff();
  const status = noteStatus(note);
  // §Scribe Phase 1 — the clinician who ran the scribe signs their own reviewed AI draft here.
  const ownAiDraft = Boolean(note.aiScribe) && canCaptureScribe(role) && (note.clinicianId === actingClinicianId || note.clinicianId === actingStaffId);
  // Same language source of truth as the Refusal risk text: the patient record.
  const cardPatient = useEhr(() => AdelanteEHR.getPatient(patientId));
  const noteLanguage = cardPatient?.preferredLanguage === "es" ? "es" : "en";
  const [signDraft, setSignDraft] = useState<AttestationDraft>(emptyAttestationDraft());
  const [cosignerId, setCosignerId] = useState<string>("");
  // §Crisis escalation — a crisis-band score cannot pass silently. The signer
  // makes an ACTIVE choice, mirroring the Suboxone mouth-check gate.
  const [crisisChoice, setCrisisChoice] = useState<"" | "escalate" | "not_escalating">("");
  const [crisisReason, setCrisisReason] = useState("");
  const { t } = useI18n();
  // §Group C — CHW service notes bill at sign time. The provider the claim is
  // billed through is chosen HERE; eligibility is the shared LPHA-tier list,
  // not a second definition of "enrolled provider".
  const isChwNote = note.templateKey === "chw_service";
  const isChwBiller = isChwNote && role === "community_health_worker";
  const [chwSupervisorId, setChwSupervisorId] = useState("");
  const supervisorOptions = eligibleSupervisingProviders();
  // The banner reads the audit row the block itself wrote — same reasonCode,
  // same reason text, no parallel copy that can drift.
  const chwBlock = useEhr(() =>
    isChwNote
      ? AdelanteEHR.lastCommunityBillingBlock({
          patientId,
          service: "chw_services",
          noteId: note.id,
        })
      : undefined,
  );
  // §Phase 3b — a finalized note shows its FROZEN autofill snapshot; a draft
  // shows the live resolution, which is what gets frozen at sign time.
  const liveAutofill = useNoteAutofillSnapshots(patientId, note.templateSchema, {
    excludeNoteId: note.id,
  });
  const autofill = note.autofillSnapshots ?? liveAutofill;
  const cardOrders = useEhr(() => AdelanteEHR.listOrders(patientId));
  const noteOrders = filterSudMedsForRole(cardOrders, role, cardPatient).visible.filter(
    (o) => o.sourceNoteId === note.id,
  );
  const mustCosign = requiresCosign(role);
  const candidates = cosignerCandidates(staffName);
  const cosigner = candidates.find((c) => c.id === cosignerId);
  // §Phase 3c — what signing will ALSO do. Same selection the runner uses, so
  // the preview can never disagree with the behaviour.
  const plannedAuto = useEhr(() =>
    AdelanteEHR.plannedNoteAutomations(patientId, note.templateSchema, note.templateAnswers),
  );
  const automationRuns = useEhr(() => AdelanteEHR.listNoteAutomationRuns(note.id));
  // Structured templates gate signing: a required question left blank is the
  // same class of defect as an unattested signature.
  const missing = note.templateSchema
    ? findMissingRequired(note.templateSchema, note.templateAnswers ?? {})
    : [];
  const crisisScores = crisisTriggeringScores(note.templateSchema, note.templateAnswers ?? {});
  const crisisBlocked =
    crisisScores.length > 0 &&
    (crisisChoice === "" ||
      (crisisChoice === "not_escalating" && crisisReason.trim().length < 3));

  // §EHR audit Phase 1d — ONE ordered list of everything blocking the
  // signature (domain problems first, ceremony last), the generalized
  // `refusalFinalizeProblems()` pattern.
  const signStatement = attestationStatement("progress_note_sign");
  const domainBlockers: SignBlocker[] = [];
  for (const m of missing)
    domainBlockers.push({
      code: `template_field_${m.key}`,
      message:
        m.problem === "invalid"
          ? `Fix “${m.label}” — ${m.reason}`
          : `Answer the required field “${m.label}”.`,
    });
  if (crisisBlocked)
    domainBlockers.push({
      code: "crisis_decision",
      message:
        crisisChoice === "not_escalating"
          ? "Give a reason of at least 3 characters for not escalating."
          : "Choose whether you are escalating this crisis-band score.",
    });
  if (mustCosign && !cosignerId)
    domainBlockers.push({ code: "cosigner_missing", message: "Choose a cosigner for this note." });
  // §Scribe Phase 1 — mirrors the store gate in signProgressNote.
  if (note.aiScribe) {
    if (!note.aiScribe.openedAt) domainBlockers.push({ code: "ai_draft_unopened", message: "Open the AI draft and review it." });
    if (note.aiScribe.unresolved > 0)
      domainBlockers.push({ code: "ai_draft_unsupported", message: `Resolve ${note.aiScribe.unresolved} sentence(s) marked "Not found in transcript".` });
    if (!note.aiScribe.reviewConfirmedAt)
      domainBlockers.push({ code: "ai_draft_unconfirmed", message: "Confirm \"I reviewed and edited this note\"." });
  }
  const signBlockers = mergeBlockers(domainBlockers, attestationBlockers(signDraft));


  const sign = () => {
    try {
      if (signBlockers.length > 0) {
        toast.error(signBlockers[0]!.message);
        return;
      }
      const attestation = buildAttestationRecord({
        statement: signStatement,
        draft: signDraft,
        signedBy: staffName,
      });
      act("progress_note", "signProgressNote", patientId, note.id, {
        signedBy: staffName,
        signedById: actingClinicianId ?? actingStaffId ?? staffName,
        role,
        attested: true,
        attestation,
        cosignRequired: mustCosign,
        cosignRole: cosigner ? [cosigner.role] : undefined,
        crisisDecision:
          crisisScores.length === 0
            ? undefined
            : crisisChoice === "escalate"
              ? { kind: "escalate" }
              : { kind: "not_escalating", reason: crisisReason },
        // Freeze what the autofill cards showed at attestation time.
        autofillSnapshots: liveAutofill.length ? liveAutofill : undefined,
      });

      // §Phase 1e — mirror into the encounter signature ledger so a claim
      // linked to this note's visit advances `documented → signed`, exactly as
      // the queue path does. Cosign-pending notes are not signed yet.
      if (!mustCosign)
        mirrorNoteSignatureToLedger(patientId, note.id);

      toast.success(mustCosign ? "Signed — routed for cosignature" : "Note signed");
      // §Phase 3 — a signed CHW service note bills through the same claims
      // pipeline. The hook itself enforces ECM exclusivity, the supervising
      // provider link and the 2 hr/day unit cap, and audits any refusal.
      if (isChwBiller) {
        const mins = Number(note.templateAnswers?.["service_minutes"] ?? 0) || 0;
        const claim = AdelanteEHRExt.upsertClaimFromChwNote({
          patientId,
          noteId: note.id,
          staffId: actingStaffId,
          clinicianId: actingClinicianId ?? note.clinicianId,
          dateISO: note.date,
          minutes: mins,
          // Explicit `null` when nothing is picked: "asked and not selected"
          // is a refusal, not a fall-through to the standing link.
          supervisingStaffId: chwSupervisorId || null,
        });
        if (claim) toast.success(`Claim created · ${claim.serviceCode} × ${claim.units}`);
        else toast.error("No CHW claim created — see the reason on the note.");
      }
      setSignDraft(emptyAttestationDraft());
      setCrisisChoice("");
      setCrisisReason("");
    } catch (e) {
      toast.error((e as Error).message);
    }
  };

  return (
    <Card className="p-3 text-xs">
      <div className="flex items-center justify-between gap-2">
        <div className="flex items-center gap-1.5">
          <Badge variant="outline" className="capitalize">
            {note.sessionType.replace("_", " ")}
          </Badge>
          <NoteStatusBadge note={note} />
          {note.category === "sud" && (
            <StatusChip lang="en" state="restricted" label="42 CFR 2" />
          )}
          {note.authorSource === "ai_draft" && (
            <Badge className="bg-muted text-muted-foreground border-0 text-[10px]" data-testid="ai-draft-badge">
              {note.aiScribe ? (note.status === "draft" || !note.status ? "AI draft — review required" : "AI-assisted") : "Machine draft"}
            </Badge>
          )}
        </div>
        <span className="text-[10px] text-muted-foreground">
          <ClientDate value={note.date} />
        </span>
      </div>
      <div className="mt-1 text-[10px] text-muted-foreground">By {authorLabel}</div>
      <AutoStartedNoteTrace note={note} />
      {sudLocked ? (
        <div className="mt-2 flex items-center gap-2 text-muted-foreground">
          <Lock className="h-3.5 w-3.5" />
          <span>{sudReason ?? "SUD note — 42 CFR Part 2 consent required"}</span>
        </div>
      ) : (
        <>
          {note.templateSchema && (
            <div className="mt-2 rounded-md border border-border p-2">
              {note.templateTitle && (
                <p className="text-muted-foreground mb-1.5 text-[10px]">
                  Answered against {note.templateTitle}
                  {note.templateVersion ? ` v${note.templateVersion}` : ""}
                </p>
              )}
              <TemplateForm
                schema={note.templateSchema}
                answers={note.templateAnswers ?? {}}
                onChange={() => {}}
                readOnly
                missingKeys={missing.map((m) => m.key)}
                language={noteLanguage}
                renderSection={(section) =>
                  section.type === "orders_section" ? (
                    canWrite && status === "draft" ? (
                      <NoteOrdersSection
                        patientId={patientId}
                        section={section}
                        sourceNoteId={note.id}
                        stagedIds={noteOrders
                          .filter((o) => o.status === "draft")
                          .map((o) => o.id)}
                        onStage={() => {}}
                      />
                    ) : (
                      <NoteOrderTrace orders={noteOrders} title={section.title} />
                    )
                  ) : (
                    (() => {
                      const snap = autofill.find((s) => s.sectionId === section.id);
                      return snap ? <NoteAutofillCard snapshot={snap} /> : null;
                    })()
                  )
                }
              />
            </div>
          )}
          <dl className="mt-2 space-y-1.5">
            {(["subjective", "objective", "assessment", "plan"] as const).map((k) =>
              note[k] ? (
                <div key={k}>
                  <dt className="font-medium text-navy capitalize">{k}</dt>
                  <dd className="text-foreground/80">{note[k]}</dd>
                </div>
              ) : null,
            )}
          </dl>
        </>
      )}
      {note.signedAt && (
        <p className="mt-2 text-[10px] text-muted-foreground">
          Signed by {note.signedBy} · <ClientDate value={note.signedAt} />
        </p>
      )}
      {note.cosignedAt && (
        <p className="text-[10px] text-muted-foreground">
          Cosigned by {note.cosignedBy} · <ClientDate value={note.cosignedAt} />
          {note.cosignComment ? ` — “${note.cosignComment}”` : ""}
        </p>
      )}
      {!sudLocked && note.aiScribe?.sessionId && <div className="mt-2"><ScribeDraftReview sessionId={note.aiScribe.sessionId} compact /></div>}
      {!sudLocked && <NoteRevisionPanel patientId={patientId} note={note} canWrite={canWrite} />}
      {note.declineReason && status === "draft" && (
        <p className="mt-2 rounded border-2 border-input bg-surface-sunk p-2 text-[11px] text-attention"><CircleAlert className="mr-1 inline size-4 shrink-0 align-text-bottom" aria-hidden="true" />
          Cosign declined by {note.declinedBy}: {note.declineReason} — revise and re-sign.
        </p>
      )}
      {automationRuns.length > 0 && (
        <div className="mt-2 rounded border border-border bg-secondary/20 p-2 text-[10px] text-muted-foreground">
          <span className="font-medium text-navy">Automations run on signing</span>
          <ul className="mt-1 space-y-0.5">
            {automationRuns.map((r) => (
              <li key={`${r.noteId}-${r.automationId}`}>
                {r.resultKind === "case_task" && "Task scheduled"}
                {r.resultKind === "draft_note" && "Draft note started"}
                {r.resultKind === "skipped" && `Skipped (${r.skipReason ?? "no result"})`} ·{" "}
                <ClientDate value={r.ranAt} />
              </li>
            ))}
          </ul>
        </div>
      )}
      <NoteExportButton patientId={patientId} note={note} authorLabel={authorLabel} />
      {chwBlock && (
        <div
          data-testid="chw-billing-block-banner"
          className="mt-2 rounded border-2 border-input bg-surface-sunk p-2 text-[11px] text-attention"
        >
          <p className="font-medium">
            {t("chwBlockTitle")} —{" "}
            <span className="font-mono" data-testid="chw-block-reason-code">
              {chwBlock.reasonCode}
            </span>
          </p>
          <p className="mt-0.5 text-foreground/80" data-testid="chw-block-reason">
            {chwBlock.reason}
          </p>
          <p className="mt-0.5 text-[10px] text-muted-foreground">
            {t("chwBlockReasonCode")}: {chwBlock.reasonCode} · <ClientDate value={chwBlock.at} />
          </p>
        </div>
      )}
      {(canWrite || ownAiDraft) && !sudLocked && (status === "draft" || status === "declined") && (
        <div className="mt-3 space-y-2 border-t border-border pt-3">
          {isChwBiller && (
            <div className="space-y-1.5" data-testid="chw-supervisor-picker">
              <Label className="text-[11px]">{t("chwSupervisingProvider")}</Label>
              <Select value={chwSupervisorId} onValueChange={setChwSupervisorId}>
                <SelectTrigger
                  className="h-8 text-xs"
                  aria-label="Supervising provider"
                >
                  <SelectValue placeholder={t("chwSupervisingNone")} />
                </SelectTrigger>
                <SelectContent>
                  {supervisorOptions.map((s) => (
                    <SelectItem key={s.id} value={s.id}>
                      {s.name}
                      {s.credential ? `, ${s.credential}` : ""}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <p className="text-[10px] text-muted-foreground">{t("chwSupervisingHelp")}</p>
            </div>
          )}
          {crisisScores.length > 0 && (
            <div
              data-testid="crisis-band-prompt"
              className="rounded border border-destructive/50 bg-destructive/5 p-2 text-[11px] text-navy"
            >
              <p className="font-medium text-destructive">
                Crisis band reached — a decision is required before signing.
              </p>
              <ul className="mt-1 list-disc space-y-0.5 pl-4">
                {crisisScores.map((s) => (
                  <li key={s.id}>{describeCrisisScore(s)}</li>
                ))}
              </ul>
              <div className="mt-2 flex flex-wrap gap-1.5">
                <Button
                  size="sm"
                  variant={crisisChoice === "escalate" ? "destructive" : "outline"}
                  onClick={() => setCrisisChoice("escalate")}
                >
                  Escalate now
                </Button>
                <Button
                  size="sm"
                  variant={crisisChoice === "not_escalating" ? "secondary" : "outline"}
                  onClick={() => setCrisisChoice("not_escalating")}
                >
                  Not escalating
                </Button>
              </div>
              {crisisChoice === "escalate" && (
                <p className="mt-1.5 text-muted-foreground">
                  Signing will create a critical alert and an open entry in the crisis queue.
                </p>
              )}
              {crisisChoice === "not_escalating" && (
                <div className="mt-1.5 space-y-1">
                  <Label className="text-[11px]">Reason for not escalating (required)</Label>
                  <Textarea
                    value={crisisReason}
                    onChange={(e) => setCrisisReason(e.target.value)}
                    rows={2}
                    aria-label="Reason for not escalating"
                  />
                </div>
              )}
            </div>
          )}
          {plannedAuto.length > 0 && (
            <div
              data-testid="pre-sign-automation-summary"
              className="rounded border border-teal/40 bg-teal/10 p-2 text-[11px] text-navy"
            >
              <span className="font-medium">
                Signing this note will also
                {mustCosign ? " (once cosigned)" : ""}:
              </span>
              <ul className="mt-1 list-disc space-y-0.5 pl-4">
                {plannedAuto.map((a) => (
                  <li key={a.id}>{summarizeAutomation(a)}</li>
                ))}
              </ul>
            </div>
          )}
          {mustCosign && (
            <div className="space-y-1.5">
              <Label className="text-[11px]">Cosigner (required for your role)</Label>
              <Select value={cosignerId} onValueChange={setCosignerId}>
                <SelectTrigger className="h-8 text-xs" aria-label="Cosigner">
                  <SelectValue placeholder="Choose a cosigner…" />
                </SelectTrigger>
                <SelectContent>
                  {candidates.map((c) => (
                    <SelectItem key={c.id} value={c.id}>
                      {c.name}
                      {c.credential ? `, ${c.credential}` : ""}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <p className="text-[10px] text-muted-foreground">
                {role.replace("_", " ")} cannot self-sign a clinical note.
              </p>
            </div>
          )}
          <SignBlockerList blockers={signBlockers} />
          <AttestationSignatureBlock
            statement={signStatement}
            draft={signDraft}
            onChange={setSignDraft}
          />
          <Button
            size="sm"
            className="w-full bg-navy text-navy-foreground hover:bg-navy/90"
            disabled={signBlockers.length > 0}
            onClick={sign}
          >
            Sign note
          </Button>

        </div>
      )}
    </Card>
  );
}

// ---------- Tracking tab (screener trends, SUD per-item masked) ----------
function TrackingTimeline({ patient, role }: { patient: Patient; role: StaffRole }) {
  const [instrument, setInstrument] = useState<string>("all");
  const [status, setStatus] = useState<"all" | "completed" | "missed">("all");
  const [from, setFrom] = useState("");
  const [to, setTo] = useState("");
  const all = buildTrackingRows(patient, role);
  const instruments = Array.from(new Set(all.map((r) => r.label))).sort();
  // R53 part 2 — a Re-screens due chip opens Tracking at its instrument (#instrument=<key>); only visible rows match.
  useEffect(() => {
    const want = /instrument=([^&]+)/.exec(window.location.hash)?.[1];
    const label = want ? all.find((r) => r.key === decodeURIComponent(want))?.label : undefined;
    if (label) setInstrument(label);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [patient.id]);
  const rows = filterTrackingRows(all, {
    instrument: instrument === "all" ? undefined : instrument,
    status,
    from: from || undefined,
    to: to || undefined,
  });
  const trend =
    instrument !== "all"
      ? rows
          .filter((r) => r.status === "completed" && r.trendable && !r.estimated && typeof r.score === "number")
          .slice()
          .reverse()
          .map((r) => ({ date: new Date(r.date).toLocaleDateString(), score: r.score }))
      : [];
  return (
    <div className="rounded-md border p-3 space-y-3" data-testid="tracking-timeline">
      <h4 className="font-medium text-navy text-sm">All screeners &amp; assessments</h4>
      <div className="flex flex-wrap items-end gap-2 text-xs">
        <label className="flex flex-col gap-1">
          Instrument
          <select
            data-testid="tracking-filter-instrument"
            className="h-9 rounded-md border bg-background px-2"
            value={instrument}
            onChange={(e) => setInstrument(e.target.value)}
          >
            <option value="all">All</option>
            {instruments.map((i) => (
              <option key={i} value={i}>{i}</option>
            ))}
          </select>
        </label>
        <label className="flex flex-col gap-1">
          Status
          <select
            data-testid="tracking-filter-status"
            className="h-9 rounded-md border bg-background px-2"
            value={status}
            onChange={(e) => setStatus(e.target.value as typeof status)}
          >
            <option value="all">Completed and missed</option>
            <option value="completed">Completed</option>
            <option value="missed">Missed or follow-up needed</option>
          </select>
        </label>
        <label className="flex flex-col gap-1">
          From
          <input type="date" data-testid="tracking-filter-from" className="h-9 rounded-md border bg-background px-2" value={from} onChange={(e) => setFrom(e.target.value)} />
        </label>
        <label className="flex flex-col gap-1">
          To
          <input type="date" data-testid="tracking-filter-to" className="h-9 rounded-md border bg-background px-2" value={to} onChange={(e) => setTo(e.target.value)} />
        </label>
      </div>
      {trend.length >= 2 && (
        <ChartFrame title="Score trend" rows={trend as unknown as Record<string, unknown>[]} columns={[{ key: "date", label: "Date" }, { key: "score", label: "Score" }]} testId="tracking-timeline-trend-frame">
        <div className="h-36" data-testid="tracking-timeline-trend">
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={trend}>
              <CartesianGrid {...chartDefaults.grid} />
              <XAxis dataKey="date" fontSize={11} />
              <YAxis fontSize={11} />
              <RTooltip />
              <Line type="monotone" dataKey="score" stroke={SINGLE_COLOR} strokeWidth={2} dot={{ r: 4 }} />
            </LineChart>
          </ResponsiveContainer>
        </div>
        </ChartFrame>
      )}
      {rows.length === 0 ? (
        <p className="text-xs text-muted-foreground">No entries match these filters.</p>
      ) : (
        <div className="overflow-x-auto">
          <table className="w-full text-xs" data-testid="tracking-timeline-table">
            <thead className="text-left text-muted-foreground">
              <tr>
                <th className="py-1 pr-2">Date</th>
                <th className="py-1 pr-2">Instrument</th>
                <th className="py-1 pr-2">Score</th>
                <th className="py-1 pr-2">Severity / level</th>
                <th className="py-1">Status</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((r, i) => (
                <tr key={`${r.key}-${r.date}-${i}`} className="border-t" data-status={r.status}>
                  <td className="py-1 pr-2 whitespace-nowrap">{new Date(r.date).toLocaleDateString()}</td>
                  <td className="py-1 pr-2">{r.label}</td>
                  <td className="py-1 pr-2 tabular-nums">{r.score ?? "—"} {estimateLabel(r)}</td>
                  <td className="py-1 pr-2">{r.level ? `Level ${r.level}` : (r.severity ?? "—")}</td>
                  <td className="py-1">
                    <StatusChip lang="en" state={r.status === "completed" ? "done" : "yourturn"} label={r.status === "completed" ? "Completed" : r.status === "missed" ? "Missed" : "Follow-up needed"} />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

export function TrackingTab({ patientId }: { patientId: string }) {
  const patient = useEhr(() => AdelanteEHR.getPatient(patientId));
  const [role] = useActingRole();
  if (!patient) return null;
  const history = patient.screenerHistory ?? [];
  // §Phase 10a — a retired form is its own series (never mixed with the
  // validated instrument's trend line); C-SSRS is listed, not charted.
  const seriesKey = (h: { key: string; retiredForm?: boolean }) => (h.retiredForm ? `${h.key}::retired` : h.key);
  const screenerKeys = Array.from(
    new Set(history.filter((h) => h.key !== CSSRS_KEY).map(seriesKey)),
  );
  const cssrs = history
    .filter((h) => h.key === CSSRS_KEY)
    .sort((a, b) => +new Date(b.completedAt) - +new Date(a.completedAt));
  const sudGate = canAccess(role, "screeners_sud", patient);
  const seesSud = roleSeesSudInstruments(role, patient);
  const drafts = listScreenerDrafts(patientId);
  const incomplete = [...(patient.incompleteScreeners ?? [])].sort((a, b) => b.completedAt.localeCompare(a.completedAt));
  return (
    <div className="space-y-6">
      <TrackingTimeline patient={patient} role={role} />
      {drafts.length > 0 && (
        <div className="flex flex-wrap gap-2" data-testid="tracking-screener-drafts">
          {drafts.map((d) => (
            <span
              key={d.key}
              className="rounded-full bg-amber-500/15 px-2.5 py-1 text-xs font-medium text-amber-700"
              data-testid={`tracking-draft-${d.key}`}
            >
              {screenerByKey(d.key)?.name ?? (d.key === CSSRS_KEY ? "C-SSRS Screener" : d.key)} — {SCREENER_DRAFT_IN_PROGRESS_LABEL}
            </span>
          ))}
        </div>
      )}
      {incomplete.length > 0 && (
        <div className="rounded-md border p-3 space-y-1" data-testid="tracking-incomplete-screeners">
          <h4 className="font-medium text-sm">Incomplete screeners</h4>
          <p className="text-xs text-muted-foreground">
            No total or severity is shown for an incomplete screener. {SCREENER_COMPLETENESS_DRAFT_LABEL}
          </p>
          <ul className="space-y-1 text-xs">
            {incomplete.map((h, i) => {
              const def = screenerByKey(h.key);
              const name = def?.name ?? h.key;
              if (def?.isSud && !seesSud) return null;
              if (def?.isSud && sudGate.locked) return <li key={i}><LockedNote reason={sudGate.reason} /></li>;
              return (
                <li key={i} className="flex flex-wrap gap-2" data-testid={`tracking-incomplete-${h.key}`}>
                  <span>{new Date(h.completedAt).toLocaleDateString()}</span>
                  <span className="font-medium">{name}</span>
                  <span>Incomplete · {answeredLabel(h)}</span>
                  {h.key === "phq-9" && h.unansweredItems.includes(8) && (
                    <span data-testid="tracking-item9-not-answered">Item 9: {itemDisplay(h, 8)}</span>
                  )}
                </li>
              );
            })}
          </ul>
        </div>
      )}
      <div className="space-y-2 text-sm" data-testid="tracking-answer-details">
        {history.filter((h) => h.unansweredItems?.length && (!screenerByKey(h.key)?.isSud || (seesSud && !sudGate.locked))).map((h) => (
          <div key={`${h.key}:${h.completedAt}`}>
            <span>{screenerByKey(h.key)?.name ?? h.key} · {h.score} · {estimateLabel(h)}</span>
            {h.unansweredItems?.map((i) => <span key={i} className="ml-2">Item {i + 1}: {itemDisplay(h, i)}</span>)}
          </div>
        ))}
        {incomplete.filter((h) => !screenerByKey(h.key)?.isSud || (seesSud && !sudGate.locked)).map((h) => (
          <div key={`${h.key}:${h.completedAt}`}>
            <span>{screenerByKey(h.key)?.name ?? h.key} · Incomplete</span>
            {h.unansweredItems.map((i) => <span key={i} className="ml-2">Item {i + 1}: {itemDisplay(h, i)}</span>)}
          </div>
        ))}
      </div>
      <LabsAndMeasuresTracking patientId={patientId} role={role} />
      <div className="rounded-md border p-3 space-y-2" data-testid="tracking-cssrs">
        <div className="flex flex-wrap items-center gap-2">
          <h4 className="font-medium text-navy text-sm flex-1">C-SSRS Screener</h4>
          <CssrsStaffControl patientId={patientId} />
        </div>
        {cssrs.length === 0 ? (
          <p className="text-xs text-muted-foreground">No C-SSRS on file.</p>
        ) : (
          <ul className="space-y-1 text-xs">
            {cssrs.map((h, i) => (
              <li key={i} className="flex flex-wrap gap-2">
                <span>{new Date(h.completedAt).toLocaleDateString()}</span>
                <span className="font-medium">{h.severity}</span>
                <span className="text-muted-foreground">
                  {h.context === "patient_self" ? "Patient self-report" : `Staff: ${h.administeredBy?.enteredBy.staffName ?? "—"}`}
                  {h.placeholderText ? " · placeholder item text" : ""} · risk mapping draft
                </span>
              </li>
            ))}
          </ul>
        )}
      </div>
      {screenerKeys.length === 0 && (
        <p className="text-sm text-muted-foreground">No screener history yet.</p>
      )}
      {screenerKeys.map((sk) => {
        const retired = sk.endsWith("::retired");
        const key = retired ? sk.replace("::retired", "") : sk;
        const def = screenerByKey(key);
        const rows = history.filter((h) => seriesKey(h) === sk);
        const title = retired
          ? `${def?.name ?? key} — retired, non-validated form (not trended with validated scores)`
          : (def?.name ?? key);
        if (def?.isSud && !seesSud) return null;
        if (def?.isSud && sudGate.locked) {
          return (
            <div key={sk}>
              <h4 className="font-medium text-navy text-sm">{title}</h4>
              <LockedNote reason={sudGate.reason} />
            </div>
          );
        }
        const data = rows
          .sort((a, b) => +new Date(a.completedAt) - +new Date(b.completedAt))
          .map((h) => ({
            date: new Date(h.completedAt).toLocaleDateString(),
            score: h.score,
            severity: `${h.severity}${estimateLabel(h) ? ` · ${estimateLabel(h)}` : ""}`,
            timepoint: h.timepoint,
          }));
        const last = rows[rows.length - 1];
        const pending = incomplete.filter(h => h.key === key).sort((a,b) => b.completedAt.localeCompare(a.completedAt))[0];
        const newestIncomplete = pending && (!last || pending.completedAt >= last.completedAt) ? pending : undefined;
        return (
          <div key={sk} data-testid={`tracking-${sk}`}>
            <div className="flex items-baseline justify-between gap-2">
              <h4 className="font-medium text-navy text-sm">{title}</h4>
              <span className="text-[11px] text-muted-foreground">
                Latest: {newestIncomplete ? `Incomplete · ${answeredLabel(newestIncomplete)}` : `${data[data.length - 1]?.score} · ${data[data.length - 1]?.severity}`}
                {mayIncludeUnanswered(last) ? ` · ${LEGACY_MAY_INCLUDE_UNANSWERED}` : ""}
              </span>
            </div>
            <p className="text-[11px] text-muted-foreground">
              {last?.instrumentVersion ? `Version ${last.instrumentVersion}` : ""}
              {last?.scoringVersion ? ` · scoring ${last.scoringVersion}` : ""}
              {last && last.textVerified === false ? " · item text pending verification" : ""}
              {def?.cutoffDraft ? " · cutoff draft pending clinical sign-off" : ""}
            </p>
            <ChartFrame title={`${title} scores`} rows={data} columns={[{ key: "date", label: "Date" }, { key: "score", label: "Score" }, { key: "severity", label: "Severity" }, { key: "timepoint", label: "Timepoint" }]} testId={`tracking-${sk}-frame`}>
            <div className="h-40 mt-2">
              <ResponsiveContainer width="100%" height="100%">
                <LineChart data={data}>
                  <CartesianGrid {...chartDefaults.grid} />
                  <XAxis dataKey="date" fontSize={11} />
                  <YAxis fontSize={11} />
                  <RTooltip />
                  {data.map((d, i) =>
                    d.timepoint && d.timepoint !== "adhoc" ? (
                      <ReferenceLine
                        key={i}
                        x={d.date}
                        stroke={chartDefaults.axis.stroke}
                        strokeDasharray="4 4"
                        label={{ value: d.timepoint, fontSize: 10, fill: "var(--ink-muted)" }}
                      />
                    ) : null,
                  )}
                  <Line
                    type="monotone"
                    dataKey="score"
                    stroke={SINGLE_COLOR}
                    strokeWidth={2}
                    dot={{ r: 4 }}
                  />
                </LineChart>
              </ResponsiveContainer>
            </div>
            </ChartFrame>
          </div>
        );
      })}
    </div>
  );
}
